module decoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic         decoder_data_valid_in, // Input data valid signal
    input  logic [65:0]  decoder_data_in,     // 66-bit encoded input
    output logic [63:0]  decoder_data_out,    // Decoded 64-bit data output
    output logic [7:0]   decoder_control_out, // Decoded 8-bit control output
    output logic         sync_error,          // Sync error flag
    output logic         decoder_error_out    // Type field error flag
);

    logic [1:0] sync_header;
    logic [7:0] type_field;
    logic [63:0] data_in;
    logic type_field_valid;
    logic decoder_wrong_ctrl_received;
    logic decoder_wrong_type_field;

    assign sync_header = decoder_data_in[65:64];
    assign type_field = decoder_data_in[63:56];
    assign data_in = {8'h00, decoder_data_in[55:0]};

    // ------------------------------------------------------------------
    // Control-character constants
    // ------------------------------------------------------------------
    localparam logic [7:0] CTRL_I = 8'h07; // /I/ Idle
    localparam logic [7:0] CTRL_S = 8'hFB; // /S/ Start of Frame
    localparam logic [7:0] CTRL_T = 8'hFD; // /T/ End of Frame
    localparam logic [7:0] CTRL_E = 8'hFE; // /E/ Error
    localparam logic [7:0] CTRL_Q = 8'h9C; // /Q/ Ordered Set

    // Payload byte lanes: Dx = data_in[8x+7 : 8x]
    logic [7:0] d6, d5, d4, d3, d2, d1, d0;
    assign d6 = data_in[55:48];
    assign d5 = data_in[47:40];
    assign d4 = data_in[39:32];
    assign d3 = data_in[31:24];
    assign d2 = data_in[23:16];
    assign d1 = data_in[15:8];
    assign d0 = data_in[7:0];

    // Combinationally decoded (pre-register) values for control/mixed mode
    logic [63:0] decoded_data;
    logic [7:0]  decoded_ctrl;

    // ------------------------------------------------------------------
    // Type-field decode table (control / mixed mode, sync header 2'b10)
    // Dx maps to byte lane x of data_in (data_in[8x+7 : 8x]);
    // control characters are fixed constants at their byte lanes.
    // Control-output masks follow the specification table bit-for-bit.
    // ------------------------------------------------------------------
    always_comb begin
        type_field_valid = 1'b1;
        decoded_data     = 64'h0;
        decoded_ctrl     = 8'h00;
        case (type_field)
            8'h1E: begin // {E7,E6,E5,E4,E3,E2,E1,E0}
                decoded_ctrl = 8'b11111111;
                decoded_data = {8{CTRL_E}};
            end
            8'h33: begin // {D6,D5,D4,S4,I3,I2,I1,I0}
                decoded_ctrl = 8'b00011111;
                decoded_data = {d6, d5, d4, CTRL_S, {4{CTRL_I}}};
            end
            8'h78: begin // {D6,D5,D4,D3,D2,D1,D0,S0}
                decoded_ctrl = 8'b00000001;
                decoded_data = {d6, d5, d4, d3, d2, d1, d0, CTRL_S};
            end
            8'h87: begin // {I7,I6,I5,I4,I3,I2,I1,T0}
                decoded_ctrl = 8'b11111110;
                decoded_data = {{7{CTRL_I}}, CTRL_T};
            end
            8'h99: begin // {I7,I6,I5,I4,I3,I2,T1,D0}
                decoded_ctrl = 8'b11111110;
                decoded_data = {{6{CTRL_I}}, CTRL_T, d0};
            end
            8'hAA: begin // {I7,I6,I5,I4,I3,T2,D1,D0}
                decoded_ctrl = 8'b11111100;
                decoded_data = {{5{CTRL_I}}, CTRL_T, d1, d0};
            end
            8'hB4: begin // {I7,I6,I5,I4,T3,D2,D1,D0}
                decoded_ctrl = 8'b11111000;
                decoded_data = {{4{CTRL_I}}, CTRL_T, d2, d1, d0};
            end
            8'hCC: begin // {I7,I6,I5,T4,D3,D2,D1,D0}
                decoded_ctrl = 8'b11110000;
                decoded_data = {{3{CTRL_I}}, CTRL_T, d3, d2, d1, d0};
            end
            8'hD2: begin // {I7,I6,T5,D4,D3,D2,D1,D0}
                decoded_ctrl = 8'b11100000;
                decoded_data = {{2{CTRL_I}}, CTRL_T, d4, d3, d2, d1, d0};
            end
            8'hE1: begin // {I7,T6,D5,D4,D3,D2,D1,D0}
                decoded_ctrl = 8'b11000000;
                decoded_data = {CTRL_I, CTRL_T, d5, d4, d3, d2, d1, d0};
            end
            8'hFF: begin // {T7,D6,D5,D4,D3,D2,D1,D0}
                decoded_ctrl = 8'b10000000;
                decoded_data = {CTRL_T, d6, d5, d4, d3, d2, d1, d0};
            end
            8'h2D: begin // {D6,D5,D4,Q4,I3,I2,I1,I0}
                decoded_ctrl = 8'b00011111;
                decoded_data = {d6, d5, d4, CTRL_Q, {4{CTRL_I}}};
            end
            8'h4B: begin // {I7,I6,I5,I4,D2,D1,D0,Q0}
                decoded_ctrl = 8'b11110001;
                decoded_data = {{4{CTRL_I}}, d2, d1, d0, CTRL_Q};
            end
            8'h55: begin // {D6,D5,D4,Q4,D2,D1,D0,Q0}
                decoded_ctrl = 8'b00010001;
                decoded_data = {d6, d5, d4, CTRL_Q, d2, d1, d0, CTRL_Q};
            end
            8'h66: begin // {D6,D5,D4,S4,D2,D1,D0,Q0}
                decoded_ctrl = 8'b00010001;
                decoded_data = {d6, d5, d4, CTRL_S, d2, d1, d0, CTRL_Q};
            end
            default: begin
                type_field_valid = 1'b0;
                decoded_data     = 64'h0;
                decoded_ctrl     = 8'h00;
            end
        endcase
    end

    // ------------------------------------------------------------------
    // Error causes (kept on separate signals and separate flags):
    //   - invalid sync header  -> sync_error only (never decoder_error_out)
    //   - invalid type field   -> decoder_error_out only (never sync_error)
    // The fixed decode table defines every control lane as a constant, so
    // no payload-pattern mismatch can occur beyond the type whitelist;
    // decoder_wrong_ctrl_received therefore never asserts.
    // ------------------------------------------------------------------
    assign decoder_wrong_type_field    = (sync_header == 2'b10) && !type_field_valid;
    assign decoder_wrong_ctrl_received = 1'b0;

    // ------------------------------------------------------------------
    // Registered outputs: 1-cycle latency, async active-high reset,
    // hold previous outputs when the valid strobe is deasserted.
    // ------------------------------------------------------------------
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            decoder_data_out    <= 64'h0;
            decoder_control_out <= 8'h00;
            sync_error          <= 1'b0;
            decoder_error_out   <= 1'b0;
        end else if (decoder_data_valid_in) begin
            case (sync_header)
                2'b01: begin // data-only mode: pass the 64-bit payload through
                    decoder_data_out    <= decoder_data_in[63:0];
                    decoder_control_out <= 8'h00;
                    sync_error          <= 1'b0;
                    decoder_error_out   <= 1'b0;
                end
                2'b10: begin // control-only or mixed mode
                    if (type_field_valid) begin
                        decoder_data_out    <= decoded_data;
                        decoder_control_out <= decoded_ctrl;
                        decoder_error_out   <= decoder_wrong_ctrl_received;
                    end else begin
                        decoder_data_out    <= 64'h0;
                        decoder_control_out <= 8'h00;
                        decoder_error_out   <= decoder_wrong_type_field |
                                               decoder_wrong_ctrl_received;
                    end
                    sync_error <= 1'b0;
                end
                default: begin // invalid sync header
                    decoder_data_out    <= 64'h0;
                    decoder_control_out <= 8'h00;
                    sync_error          <= 1'b1;
                    decoder_error_out   <= 1'b0;
                end
            endcase
        end
        // no else branch: outputs hold their value when valid is deasserted
    end

endmodule

module encoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [63:0]  encoder_data_in,     // 64-bit data input
    input  logic [7:0]   encoder_control_in,  // 8-bit control input
    output logic [65:0]  encoder_data_out     // 66-bit encoded output
);

    // ------------------------------------------------------------------
    // Valid control-character byte values on the input
    // ------------------------------------------------------------------
    localparam logic [7:0] CHAR_I = 8'h07;   // /I/ Idle
    localparam logic [7:0] CHAR_S = 8'hfb;   // /S/ Start of Frame
    localparam logic [7:0] CHAR_T = 8'hfd;   // /T/ End of Frame
    localparam logic [7:0] CHAR_E = 8'hfe;   // /E/ Error
    localparam logic [7:0] CHAR_Q = 8'h9c;   // /Q/ Ordered Set

    // 7-bit encoded control codes
    localparam logic [6:0] CODE_I = 7'h00;   // /I/ -> 7'h00
    localparam logic [6:0] CODE_E = 7'h1e;   // /E/ -> 7'h1e

    logic [1:0]  sync_word;
    logic [63:0] encoded_data;

    // Input byte lanes (byte i is qualified by encoder_control_in[i])
    logic [7:0] d7, d6, d5, d4, d3, d2, d1, d0;

    assign d7 = encoder_data_in[63:56];
    assign d6 = encoder_data_in[55:48];
    assign d5 = encoder_data_in[47:40];
    assign d4 = encoder_data_in[39:32];
    assign d3 = encoder_data_in[31:24];
    assign d2 = encoder_data_in[23:16];
    assign d1 = encoder_data_in[15:8];
    assign d0 = encoder_data_in[7:0];

    // 7-bit control-code lookup for a control byte carried in a C lane
    function automatic logic [6:0] ccode(input logic [7:0] b);
        case (b)
            CHAR_I:  ccode = CODE_I;
            CHAR_E:  ccode = CODE_E;
            default: ccode = CODE_E; // any other character in a C lane -> error code
        endcase
    endfunction

    // ------------------------------------------------------------------
    // Sync word: 2'b01 = data-only, 2'b10 = control-only / mixed
    // ------------------------------------------------------------------
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            sync_word <= 2'b00;
        end
        else begin
            if (encoder_control_in == 8'b00000000) begin
                sync_word <= 2'b01;
            end
            else begin
                sync_word <= 2'b10;
            end
        end
    end

    // ------------------------------------------------------------------
    // Encoded data word:
    //   data-only      -> raw 64-bit data (no type field)
    //   control/mixed  -> {8-bit type field, 56-bit encoded payload}
    // ------------------------------------------------------------------
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            encoded_data <= 64'b0;
        end
        else begin
            case (encoder_control_in)
                // Data-only mode: pass data through unchanged
                8'b00000000: encoded_data <= encoder_data_in;

                // All-control lanes:
                //   I7..I1,T0                -> type 0x87
                //   all idle / all error     -> type 0x1e
                8'b11111111: begin
                    if (d0 == CHAR_T) begin
                        encoded_data <= {8'h87, ccode(d7), ccode(d6), ccode(d5),
                                         ccode(d4), ccode(d3), ccode(d2), ccode(d1),
                                         7'b0000000};
                    end
                    else begin
                        encoded_data <= {8'h1e,
                                         1'b0, ccode(d6), 1'b0, ccode(d5),
                                         1'b0, ccode(d4), 1'b0, ccode(d3),
                                         1'b0, ccode(d2), 1'b0, ccode(d1),
                                         1'b0, ccode(d0)};
                    end
                end

                // I7..I2,T1,D0 -> type 0x99  (also tolerate T0 driven with this mask)
                8'b11111110: begin
                    if (d1 == CHAR_T) begin
                        encoded_data <= {8'h99, ccode(d7), ccode(d6), ccode(d5),
                                         ccode(d4), ccode(d3), ccode(d2),
                                         6'b000000, d0};
                    end
                    else if (d0 == CHAR_T) begin
                        encoded_data <= {8'h87, ccode(d7), ccode(d6), ccode(d5),
                                         ccode(d4), ccode(d3), ccode(d2), ccode(d1),
                                         7'b0000000};
                    end
                    else begin
                        encoded_data <= {8'h99, ccode(d7), ccode(d6), ccode(d5),
                                         ccode(d4), ccode(d3), ccode(d2),
                                         6'b000000, d0};
                    end
                end

                // I7..I3,T2,D1,D0 -> type 0xaa
                8'b11111100: encoded_data <= {8'haa, ccode(d7), ccode(d6), ccode(d5),
                                              ccode(d4), ccode(d3), 5'b00000, d1, d0};

                // I7..I4,T3,D2..D0 -> type 0xb4
                8'b11111000: encoded_data <= {8'hb4, ccode(d7), ccode(d6), ccode(d5),
                                              ccode(d4), 4'b0000, d2, d1, d0};

                // I7..I5,T4,D3..D0 -> type 0xcc
                8'b11110000: encoded_data <= {8'hcc, ccode(d7), ccode(d6), ccode(d5),
                                              3'b000, d3, d2, d1, d0};

                // I7,I6,T5,D4..D0 -> type 0xd2
                8'b11100000: encoded_data <= {8'hd2, ccode(d7), ccode(d6),
                                              2'b00, d4, d3, d2, d1, d0};

                // I7,T6,D5..D0 -> type 0xe1
                8'b11000000: encoded_data <= {8'he1, ccode(d7),
                                              1'b0, d5, d4, d3, d2, d1, d0};

                // T7,D6..D0 -> type 0xff
                8'b10000000: encoded_data <= {8'hff, d6, d5, d4, d3, d2, d1, d0};

                // D7,D6,D5,{S4|Q4},I3..I0 -> type 0x33 (S4) / 0x2d (Q4)
                8'b00011111: begin
                    if (d4 == CHAR_Q) begin
                        encoded_data <= {8'h2d, d7, d6, d5, 4'b1111,
                                         ccode(d3), ccode(d2), ccode(d1), ccode(d0)};
                    end
                    else begin
                        encoded_data <= {8'h33, d7, d6, d5, 4'b0000,
                                         ccode(d3), ccode(d2), ccode(d1), ccode(d0)};
                    end
                end

                // D7..D1,S0 -> type 0x78
                8'b00000001: encoded_data <= {8'h78, d7, d6, d5, d4, d3, d2, d1};

                // I7..I4,D3..D1,Q0 -> type 0x4b
                8'b11110001: encoded_data <= {8'h4b, ccode(d7), ccode(d6), ccode(d5),
                                              ccode(d4), d3, d2, d1, 4'b1111};

                // D7,D6,D5,{Q4|S4},D3,D2,D1,Q0 -> type 0x55 (Q4) / 0x66 (S4)
                8'b00010001: begin
                    if (d4 == CHAR_S) begin
                        encoded_data <= {8'h66, d7, d6, d5, 8'b00001111, d3, d2, d1};
                    end
                    else begin
                        encoded_data <= {8'h55, d7, d6, d5, 8'b11111111, d3, d2, d1};
                    end
                end

                // Any other control pattern has no valid mapping: zero payload
                default: encoded_data <= 64'b0;
            endcase
        end
    end

    assign encoder_data_out = {sync_word, encoded_data};

endmodule

// ---------------------------------------------------------------------------
// encoder_64b66b — area-optimized implementation (functionally equivalent).
//
// Optimization strategy (structural, survives synthesis):
//   1. Shared pattern comparators. The original compared the same data bytes
//      against the same constants twice — once inside the get_output()
//      function and once inside the encoded_ctrl_words case statement, using
//      wide (16..64-bit) comparators. All encoding conditions are now derived
//      from ONE set of per-byte comparators (byte == 0x07 / 0xFD) plus a
//      single prefix-AND chain for the leading 0x07 runs, so every input byte
//      is compared against every constant exactly once and each wide pattern
//      is just a 2-3 input AND of shared terms.
//   2. Merged result registers. The original held three result registers —
//      encoded_data (64b), type_field (8b) and encoded_ctrl_words (56b) —
//      that are mutually exclusive by construction: when the registered
//      control is zero the {type_field, encoded_ctrl_words} pair is all-zero,
//      and when it is non-zero encoded_data is all-zero. They are merged into
//      ONE shared 64-bit payload register (132 -> 68 flops), and the original
//      register values are reconstructed through the already-registered
//      sync_word qualifier bits.
//   3. Flat select planes. The two long priority chains (16-branch function,
//      12-branch case) are replaced by flat AND-OR planes over the mutually
//      exclusive match terms.
//
// Interface, module name, one-clock-cycle latency, asynchronous reset
// behaviour and every encoding condition — including the 56'hFFFFFFF
// fall-back for control 8'b11110000 and the hold behaviour of
// sync_ctrl_word — are bit-identical to the original module.
// ---------------------------------------------------------------------------
module encoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [63:0]  encoder_data_in,     // 64-bit data input
    input  logic [7:0]   encoder_control_in,  // 8-bit control input
    output logic [65:0]  encoder_data_out     // 66-bit encoded output
);

    // ------------------------------------------------------------------
    // Shared per-byte pattern comparators (each byte compared once).
    // ------------------------------------------------------------------
    wire [7:0] byte_is_07;   // byte k == 8'h07
    wire [7:0] byte_is_fd;   // byte k == 8'hFD
    generate
        genvar gi;
        for (gi = 0; gi < 8; gi = gi + 1) begin : g_bytecmp
            assign byte_is_07[gi] = (encoder_data_in[8*gi +: 8] == 8'h07);
            assign byte_is_fd[gi] = (encoder_data_in[8*gi +: 8] == 8'hFD);
        end
    endgenerate

    // Prefix runs: run07[k] == "bytes 7 down to k are all 0x07".
    wire [7:1] run07;
    assign run07[7] = byte_is_07[7];
    assign run07[6] = run07[7] & byte_is_07[6];
    assign run07[5] = run07[6] & byte_is_07[5];
    assign run07[4] = run07[5] & byte_is_07[4];
    assign run07[3] = run07[4] & byte_is_07[3];
    assign run07[2] = run07[3] & byte_is_07[2];
    assign run07[1] = run07[2] & byte_is_07[1];
    wire all_07  = run07[1] & byte_is_07[0];
    wire low4_07 = byte_is_07[3] & byte_is_07[2] & byte_is_07[1] & byte_is_07[0];

    wire all_fe = (encoder_data_in == 64'hFEFEFEFEFEFEFEFE);
    wire b4_fb  = (encoder_data_in[39:32] == 8'hFB);
    wire b4_9c  = (encoder_data_in[39:32] == 8'h9C);
    wire b0_fb  = (encoder_data_in[7:0]   == 8'hFB);
    wire b0_9c  = (encoder_data_in[7:0]   == 8'h9C);

    // ------------------------------------------------------------------
    // Control decodes (shared by every match term).
    // ------------------------------------------------------------------
    wire ctrl_zero = (encoder_control_in == 8'b00000000);
    wire c_ff = (encoder_control_in == 8'b11111111);
    wire c_1f = (encoder_control_in == 8'b00011111);
    wire c_01 = (encoder_control_in == 8'b00000001);
    wire c_fe = (encoder_control_in == 8'b11111110);
    wire c_fc = (encoder_control_in == 8'b11111100);
    wire c_f8 = (encoder_control_in == 8'b11111000);
    wire c_f0 = (encoder_control_in == 8'b11110000);
    wire c_e0 = (encoder_control_in == 8'b11100000);
    wire c_c0 = (encoder_control_in == 8'b11000000);
    wire c_80 = (encoder_control_in == 8'b10000000);
    wire c_f1 = (encoder_control_in == 8'b11110001);
    wire c_11 = (encoder_control_in == 8'b00010001);

    // ------------------------------------------------------------------
    // Encoding-condition matches (pairwise mutually exclusive).
    // ------------------------------------------------------------------
    wire m_idle   = c_ff & all_07;                    // type 8'h1e
    wire m_allfe  = c_ff & all_fe;                    // type 8'h1e
    wire m_term8  = c_ff & run07[1] & byte_is_fd[0];  // type 8'h87
    wire m_st4_fb = c_1f & b4_fb & low4_07;           // type 8'h33
    wire m_st4_9c = c_1f & b4_9c & low4_07;           // type 8'h2d
    wire m_st0    = c_01 & b0_fb;                     // type 8'h78
    wire m_term7  = c_fe & run07[2] & byte_is_fd[1];  // type 8'h99
    wire m_term6  = c_fc & run07[3] & byte_is_fd[2];  // type 8'haa
    wire m_term5  = c_f8 & run07[4] & byte_is_fd[3];  // type 8'hb4
    wire m_term4  = c_f0 & run07[5] & byte_is_fd[4];  // type 8'hcc
    wire m_term3  = c_e0 & run07[6] & byte_is_fd[5];  // type 8'hd2
    wire m_term2  = c_c0 & run07[7] & byte_is_fd[6];  // type 8'he1
    wire m_term1  = c_80 & byte_is_fd[7];             // type 8'hff
    wire m_ord4   = c_f1 & run07[4] & b0_9c;          // type 8'h4b
    wire m_ord0a  = c_11 & b4_9c & b0_9c;             // type 8'h55
    wire m_ord0b  = c_11 & b4_fb & b0_9c;             // type 8'h66

    // ------------------------------------------------------------------
    // Flat AND-OR select planes (valid because matches are exclusive).
    // ------------------------------------------------------------------
    wire [7:0] type_code =
          ({8{m_idle | m_allfe}} & 8'h1e)
        | ({8{m_term8 }} & 8'h87)
        | ({8{m_st4_fb}} & 8'h33)
        | ({8{m_st4_9c}} & 8'h2d)
        | ({8{m_st0   }} & 8'h78)
        | ({8{m_term7 }} & 8'h99)
        | ({8{m_term6 }} & 8'haa)
        | ({8{m_term5 }} & 8'hb4)
        | ({8{m_term4 }} & 8'hcc)
        | ({8{m_term3 }} & 8'hd2)
        | ({8{m_term2 }} & 8'he1)
        | ({8{m_term1 }} & 8'hff)
        | ({8{m_ord4  }} & 8'h4b)
        | ({8{m_ord0a }} & 8'h55)
        | ({8{m_ord0b }} & 8'h66);

    wire [55:0] ctrl_words =
          ({56{m_allfe }} & {8{7'h1E}})
        | ({56{m_st4_fb}} & {encoder_data_in[63:40], 32'h00000000})
        | ({56{m_st4_9c}} & {encoder_data_in[63:40], 4'hF, 28'h0000000})
        | ({56{m_st0   }} & encoder_data_in[63:8])
        | ({56{m_term7 }} & {48'h000000000000, encoder_data_in[7:0]})
        | ({56{m_term6 }} & {40'h0000000000, encoder_data_in[15:0]})
        | ({56{m_term5 }} & {32'h00000000, encoder_data_in[23:0]})
        | ({56{m_term4 }} & {24'h000000, encoder_data_in[31:0]})
        | ({56{m_term3 }} & {16'h0000, encoder_data_in[39:0]})
        | ({56{m_term2 }} & {8'h00, encoder_data_in[47:0]})
        | ({56{m_term1 }} & encoder_data_in[55:0])
        | ({56{m_ord4  }} & {28'h0000000, encoder_data_in[31:8], 4'hF})
        | ({56{m_ord0a }} & {encoder_data_in[63:40], 8'hFF, encoder_data_in[31:8]})
        | ({56{m_ord0b }} & {encoder_data_in[63:40], 8'h0F, encoder_data_in[31:8]})
        | ({56{c_f0 & ~m_term4}} & 56'h0000000FFFFFFF); // original F0 fall-back

    // ------------------------------------------------------------------
    // Merged sequential stage (one clock cycle latency, async reset).
    // {type_code, ctrl_words} is all-zero whenever ctrl_zero holds, so the
    // data and control payloads share one 64-bit register.
    // ------------------------------------------------------------------
    wire [63:0] payload_next =
          ({64{ctrl_zero}} & encoder_data_in)  // data payload (idle control)
        | {type_code, ctrl_words};             // control payload

    logic [63:0] payload_q;
    logic [1:0]  sync_word;
    logic [1:0]  sync_ctrl_word;

    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            payload_q      <= 64'h0;
            sync_word      <= 2'b00;
            sync_ctrl_word <= 2'b00;
        end else begin
            payload_q <= payload_next;
            sync_word <= ctrl_zero ? 2'b01 : 2'b10;
            if (!ctrl_zero)
                sync_ctrl_word <= 2'b10;   // holds its value while control is idle
        end
    end

    // Original register views, reconstructed bit-identically from the shared
    // payload through the registered sync_word qualifiers.
    wire [63:0] encoded_data       = sync_word[0] ? payload_q        : 64'h0;
    wire [7:0]  type_field         = sync_word[1] ? payload_q[63:56] : 8'h0;
    wire [55:0] encoded_ctrl_words = sync_word[1] ? payload_q[55:0]  : 56'h0;

    always_comb begin
        if (|encoder_control_in)
            encoder_data_out = {sync_ctrl_word, type_field, encoded_ctrl_words};
        else
            encoder_data_out = {sync_word, encoded_data};
    end

endmodule

// ============================================================================
// glitch_free_mux
// ----------------------------------------------------------------------------
// Glitch-free clock switching multiplexer between two synchronous clocks.
//
//   sel = 0 -> clkout = clk1
//   sel = 1 -> clkout = clk2
//
// Break-before-make protocol (all enable updates on POSITIVE clock edges,
// per specification):
//   * On sel 0 -> 1 : clk1 is disabled on the first posedge of clk1 after
//     the sel change; clk2 is then enabled on the first posedge of clk2
//     after clk1 has been disabled.
//   * On sel 1 -> 0 : clk2 is disabled on the first posedge of clk2 after
//     the sel change; clk1 is then enabled on the first posedge of clk1
//     after clk2 has been disabled.
//
// The two clock-enable registers are cross-coupled so that each clock's
// enable can only assert when the other clock's enable is deasserted,
// guaranteeing the enables are never simultaneously high and therefore the
// output clock switches without glitches (runt pulses).
//
// rst_n is an asynchronous active-low reset: while rst_n = 0 both enables
// are forced low, driving clkout low.
// ============================================================================

module glitch_free_mux (
    input  wire clk1,   // input clock 1 (selected when sel = 0)
    input  wire clk2,   // input clock 2 (selected when sel = 1)
    input  wire sel,    // clock select : 0 -> clk1 , 1 -> clk2
    input  wire rst_n,  // asynchronous active-low reset (clkout low when 0)
    output wire clkout  // glitch-free output clock
);

    // Cross-coupled break-before-make clock enables
    reg clk1_en;
    reg clk2_en;

    // clk1 domain enable: asserts only when clk1 is selected (sel = 0) AND
    // the clk2 path has already been disabled.
    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n)
            clk1_en <= 1'b0;
        else
            clk1_en <= ~sel & ~clk2_en;
    end

    // clk2 domain enable: asserts only when clk2 is selected (sel = 1) AND
    // the clk1 path has already been disabled.
    always @(posedge clk2 or negedge rst_n) begin
        if (!rst_n)
            clk2_en <= 1'b0;
        else
            clk2_en <= sel & ~clk1_en;
    end

    // Gated-clock output mux: each clock is masked by its own enable.
    // During reset both enables are 0, so clkout is driven low.
    assign clkout = (clk1 & clk1_en) | (clk2 & clk2_en);

endmodule


