// cvdp_copilot_apb_gpio
// APB-compatible GPIO peripheral with configurable width, bidirectional
// direction control, edge/level interrupt generation, and two-stage input
// synchronization.  Single-cycle (zero wait-state) APB slave: pready is held
// high and pslverr is held low per the specification.
module cvdp_copilot_apb_gpio #(
    parameter GPIO_WIDTH = 8
) (
    // -------- APB interface --------
    input  wire                    pclk,      // rising-edge clock
    input  wire                    preset_n,  // active-low async reset
    input  wire                    psel,      // peripheral select
    input  wire [7:2]              paddr,     // word-aligned address
    input  wire                    penable,   // transfer enable (ACCESS phase)
    input  wire                    pwrite,    // 1 = write, 0 = read
    input  wire [31:0]             pwdata,    // write data
    output reg  [31:0]             prdata,    // read data
    output wire                    pready,    // always high (no wait states)
    output wire                    pslverr,   // always low (no errors)

    // -------- GPIO pins --------
    input  wire [GPIO_WIDTH-1:0]   gpio_in,     // pad inputs
    output wire [GPIO_WIDTH-1:0]   gpio_out,    // pad outputs (from reg_out)
    output wire [GPIO_WIDTH-1:0]   gpio_enable, // direction: 1=output, 0=input
    output wire [GPIO_WIDTH-1:0]   gpio_int,    // per-pin interrupt
    output wire                    comb_int     // OR of all gpio_int
);

    // -----------------------------------------------------------------
    // Register-map word offsets (paddr is byte-address bits [7:2], i.e.
    // already word-aligned -> compare against byte_addr>>2).
    // -----------------------------------------------------------------
    localparam [5:0] ADDR_INPUT  = 6'd0;  // 0x00 GPIO Input Data   (RO)
    localparam [5:0] ADDR_OUTPUT = 6'd1;  // 0x04 GPIO Output Data
    localparam [5:0] ADDR_OE     = 6'd2;  // 0x08 GPIO Output Enable
    localparam [5:0] ADDR_IE     = 6'd3;  // 0x0C GPIO Interrupt Enable
    localparam [5:0] ADDR_ITYPE  = 6'd4;  // 0x10 GPIO Interrupt Type (edge/level)
    localparam [5:0] ADDR_IPOL   = 6'd5;  // 0x14 GPIO Interrupt Polarity
    localparam [5:0] ADDR_ISTATE = 6'd6;  // 0x18 GPIO Interrupt State (RO)

    // -----------------------------------------------------------------
    // Configuration registers
    // -----------------------------------------------------------------
    reg [GPIO_WIDTH-1:0] reg_out;    // output data
    reg [GPIO_WIDTH-1:0] reg_oe;     // output enable / direction
    reg [GPIO_WIDTH-1:0] reg_ie;     // interrupt enable
    reg [GPIO_WIDTH-1:0] reg_itype;  // interrupt type  : 1=edge, 0=level
    reg [GPIO_WIDTH-1:0] reg_ipol;   // interrupt polar : 1=active-high, 0=active-low

    // -----------------------------------------------------------------
    // Two-stage input synchronizer (metastability mitigation)
    // -----------------------------------------------------------------
    reg [GPIO_WIDTH-1:0] gpio_in_s1;
    reg [GPIO_WIDTH-1:0] gpio_in_s2;    // synchronized value used everywhere
    reg [GPIO_WIDTH-1:0] gpio_in_s2_d;  // delayed by one cycle for edge detect

    always @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            gpio_in_s1   <= {GPIO_WIDTH{1'b0}};
            gpio_in_s2   <= {GPIO_WIDTH{1'b0}};
            gpio_in_s2_d <= {GPIO_WIDTH{1'b0}};
        end else begin
            gpio_in_s1   <= gpio_in;
            gpio_in_s2   <= gpio_in_s1;
            gpio_in_s2_d <= gpio_in_s2;
        end
    end

    // -----------------------------------------------------------------
    // APB write logic : commit during ACCESS phase (psel & penable & pwrite).
    // pready is always high so penable is asserted for exactly one cycle per
    // transaction -> each register updates exactly once.  Read-only and
    // undefined addresses are ignored.
    // -----------------------------------------------------------------
    always @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            reg_out   <= {GPIO_WIDTH{1'b0}};
            reg_oe    <= {GPIO_WIDTH{1'b0}};
            reg_ie    <= {GPIO_WIDTH{1'b0}};
            reg_itype <= {GPIO_WIDTH{1'b0}};
            reg_ipol  <= {GPIO_WIDTH{1'b0}};
        end else if (psel && penable && pwrite) begin
            case (paddr)
                ADDR_OUTPUT: reg_out   <= pwdata[GPIO_WIDTH-1:0];
                ADDR_OE    : reg_oe    <= pwdata[GPIO_WIDTH-1:0];
                ADDR_IE    : reg_ie    <= pwdata[GPIO_WIDTH-1:0];
                ADDR_ITYPE : reg_itype <= pwdata[GPIO_WIDTH-1:0];
                ADDR_IPOL  : reg_ipol  <= pwdata[GPIO_WIDTH-1:0];
                default    : ; // RO (input/state) or undefined -> no effect
            endcase
        end
    end

    // -----------------------------------------------------------------
    // APB read logic : combinational, zero added latency.  prdata reflects
    // the addressed register during a qualified read (psel & penable & ~pwrite)
    // and is 0 when idle or for undefined addresses.  All fields are
    // zero-extended into the 32-bit data bus.
    // -----------------------------------------------------------------
    always @(*) begin
        prdata = 32'b0;
        if (psel && penable && !pwrite) begin
            case (paddr)
                ADDR_INPUT : prdata = {{(32-GPIO_WIDTH){1'b0}}, gpio_in_s2};
                ADDR_OUTPUT: prdata = {{(32-GPIO_WIDTH){1'b0}}, reg_out};
                ADDR_OE    : prdata = {{(32-GPIO_WIDTH){1'b0}}, reg_oe};
                ADDR_IE    : prdata = {{(32-GPIO_WIDTH){1'b0}}, reg_ie};
                ADDR_ITYPE : prdata = {{(32-GPIO_WIDTH){1'b0}}, reg_itype};
                ADDR_IPOL  : prdata = {{(32-GPIO_WIDTH){1'b0}}, reg_ipol};
                ADDR_ISTATE: prdata = {{(32-GPIO_WIDTH){1'b0}}, gpio_int};
                default    : prdata = 32'b0;
            endcase
        end
    end

    // -----------------------------------------------------------------
    // GPIO drive
    // -----------------------------------------------------------------
    assign gpio_out    = reg_out;
    assign gpio_enable = reg_oe;

    // -----------------------------------------------------------------
    // Interrupt generation (combinational, single-cycle response off the
    // synchronized inputs).
    //   itype = 1 : edge-sensitive,  0 : level-sensitive
    //   ipol  = 1 : active-high (rising edge / logic-high level)
    //   ipol  = 0 : active-low  (falling edge / logic-low  level)
    // Each pin is independent; comb_int is the logical OR of all pins.
    // (Simultaneous interrupts naturally coexist; comb_int asserts once.)
    // -----------------------------------------------------------------
    wire [GPIO_WIDTH-1:0] rising  =  gpio_in_s2 & ~gpio_in_s2_d;
    wire [GPIO_WIDTH-1:0] falling = ~gpio_in_s2 &  gpio_in_s2_d;

    wire [GPIO_WIDTH-1:0] edge_int  = (reg_ipol  & rising)     | (~reg_ipol  & falling);
    wire [GPIO_WIDTH-1:0] level_int = (reg_ipol  & gpio_in_s2) | (~reg_ipol  & ~gpio_in_s2);
    wire [GPIO_WIDTH-1:0] raw_int   = (reg_itype & edge_int)   | (~reg_itype & level_int);

    assign gpio_int = reg_ie & raw_int;
    assign comb_int = |gpio_int;

    // -----------------------------------------------------------------
    // Static APB status
    // -----------------------------------------------------------------
    assign pready  = 1'b1;
    assign pslverr = 1'b0;

endmodule

module cvdp_copilot_apb_gpio #(
  parameter GPIO_WIDTH = 8
)(
  // Clock and Reset Signals
  input logic pclk,       // Clock signal
  input logic preset_n,   // Active-low reset signal

  // APB Interface Inputs
  input logic psel,           // Peripheral select
  input logic [7:2] paddr,    // APB address bus (bits [7:2])
  input logic penable,        // Transfer control signal
  input logic pwrite,         // Write control signal
  input logic [31:0] pwdata,  // Write data bus

  // APB Interface Outputs
  output logic [31:0] prdata, // Read data bus
  output logic pready,        // Device ready signal
  output logic pslverr,       // Device error response

  // Bidirectional GPIO Interface
  inout wire [GPIO_WIDTH-1:0] gpio,       // Bidirectional GPIO pins

  // Interrupt Outputs
  output logic [GPIO_WIDTH-1:0] gpio_int, // Individual interrupt outputs
  output logic comb_int                   // Combined interrupt output
);

  // Signals for Read/Write Controls
  logic read_enable;                     // Read enable signal
  logic write_enable;                    // Write enable signal
  logic write_enable_reg_04;             // Write enable for Data Output register
  logic write_enable_reg_08;             // Write enable for Output Enable register
  logic write_enable_reg_0C;             // Write enable for Interrupt Enable register
  logic write_enable_reg_10;             // Write enable for Interrupt Type register
  logic write_enable_reg_14;             // Write enable for Interrupt Polarity register
  logic write_enable_reg_18;             // Write enable for Interrupt State register
  logic write_enable_reg_1C;             // Write enable for Direction Control register
  logic write_enable_reg_20;             // Write enable for Power Management register
  logic write_enable_reg_24;             // Write enable for Interrupt Reset register
  logic [GPIO_WIDTH-1:0] read_mux;       // Read data multiplexer
  logic [GPIO_WIDTH-1:0] read_mux_d1;    // Registered read data

  // Control Registers
  logic [GPIO_WIDTH-1:0] reg_dout;       // Data Output register
  logic [GPIO_WIDTH-1:0] reg_dout_en;    // Output Enable register
  logic [GPIO_WIDTH-1:0] reg_int_en;     // Interrupt Enable register
  logic [GPIO_WIDTH-1:0] reg_int_type;   // Interrupt Type register
  logic [GPIO_WIDTH-1:0] reg_int_pol;    // Interrupt Polarity register
  logic [GPIO_WIDTH-1:0] reg_int_state;  // Interrupt State register
  logic [GPIO_WIDTH-1:0] gpio_dir;       // Direction Control register (0: Input, 1: Output)
  logic reg_pwr_down;                    // Power Management register bit[0] (global power-down)

  // I/O Signal Path and Interrupt Logic
  logic [GPIO_WIDTH-1:0] data_in_sync1;            // First stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_sync2;            // Second stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted;     // Polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted_dly; // Delayed version of polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] edge_detect;              // Edge detection signals
  logic [GPIO_WIDTH-1:0] raw_int;                  // Raw interrupt signals
  logic [GPIO_WIDTH-1:0] int_masked;               // Masked interrupt signals
  logic [GPIO_WIDTH-1:0] clear_interrupt;          // Clear interrupt signals

  // Read and Write Control Signals
  assign read_enable = psel & (~pwrite); // Read enable
  assign write_enable = psel & (~penable) & pwrite; // Write enable

  // Write Enable Signals for Specific Registers
  // Global power-down masks writes to the normal control registers; the Power
  // Management register itself and the interrupt-status paths (Interrupt State
  // write-1-to-clear and the Interrupt Reset register) remain accessible so
  // software always has a path to re-enable the block and manage interrupts.
  assign write_enable_reg_04 = write_enable & (paddr[7:2] == 6'd1) & ~reg_pwr_down; // Address 0x04
  assign write_enable_reg_08 = write_enable & (paddr[7:2] == 6'd2) & ~reg_pwr_down; // Address 0x08
  assign write_enable_reg_0C = write_enable & (paddr[7:2] == 6'd3) & ~reg_pwr_down; // Address 0x0C
  assign write_enable_reg_10 = write_enable & (paddr[7:2] == 6'd4) & ~reg_pwr_down; // Address 0x10
  assign write_enable_reg_14 = write_enable & (paddr[7:2] == 6'd5) & ~reg_pwr_down; // Address 0x14
  assign write_enable_reg_18 = write_enable & (paddr[7:2] == 6'd6);                 // Address 0x18
  assign write_enable_reg_1C = write_enable & (paddr[7:2] == 6'd7) & ~reg_pwr_down; // Address 0x1C
  assign write_enable_reg_20 = write_enable & (paddr[7:2] == 6'd8);                 // Address 0x20
  assign write_enable_reg_24 = write_enable & (paddr[7:2] == 6'd9);                 // Address 0x24

  // Write Operations for Control Registers

  // Data Output Register (reg_dout)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_04)
      reg_dout <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Output Enable Register (reg_dout_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_08)
      reg_dout_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Enable Register (reg_int_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_0C)
      reg_int_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Type Register (reg_int_type)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_type <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_10)
      reg_int_type <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Polarity Register (reg_int_pol)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_pol <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_14)
      reg_int_pol <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Direction Control Register (gpio_dir) - updates synchronized to pclk
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      gpio_dir <= {GPIO_WIDTH{1'b0}}; // All pins default to input for safe start-up
    else if (write_enable_reg_1C)
      gpio_dir <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Power Management Register (reg_pwr_down) - bit[0] only, reserved bits ignored
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_pwr_down <= 1'b0; // Normal operation after reset
    else if (write_enable_reg_20)
      reg_pwr_down <= pwdata[0];
  end

  // Read Operation: Multiplexing Register Data Based on Address
  always_comb begin
    case (paddr[7:2])
      6'd0: read_mux = data_in_sync2;   // Input Data Register at address 0x00
      6'd1: read_mux = reg_dout;        // Data Output Register at address 0x04
      6'd2: read_mux = reg_dout_en;     // Output Enable Register at address 0x08
      6'd3: read_mux = reg_int_en;      // Interrupt Enable Register at address 0x0C
      6'd4: read_mux = reg_int_type;    // Interrupt Type Register at address 0x10
      6'd5: read_mux = reg_int_pol;     // Interrupt Polarity Register at address 0x14
      6'd6: read_mux = reg_int_state;   // Interrupt State Register at address 0x18
      6'd7: read_mux = gpio_dir;        // Direction Control Register at address 0x1C
      6'd8: begin                       // Power Management Register at address 0x20
        read_mux = {GPIO_WIDTH{1'b0}};
        read_mux[0] = reg_pwr_down;
      end
      default: read_mux = {GPIO_WIDTH{1'b0}}; // Default to zeros if address is invalid
    endcase
  end

  // Registering Read Data for Timing Alignment
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      read_mux_d1 <= {GPIO_WIDTH{1'b0}};
    else
      read_mux_d1 <= read_mux;
  end

  // Output Read Data to APB Interface
  assign prdata = (read_enable) ? {{(32-GPIO_WIDTH){1'b0}}, read_mux_d1} : {32{1'b0}};
  assign pready = 1'b1; // Always ready
  assign pslverr = 1'b0; // No error

  // Bidirectional GPIO Pin Drivers
  // A pin is actively driven only when its Direction Control bit configures it
  // as an output and the block is not globally powered down; otherwise the pin
  // is released to high-impedance (safe input configuration / power-down).
  generate
    genvar g;
    for (g = 0; g < GPIO_WIDTH; g = g + 1) begin : g_gpio_drive
      assign gpio[g] = (gpio_dir[g] & ~reg_pwr_down) ? reg_dout[g] : 1'bz;
    end
  endgenerate

  // Input Synchronization to Avoid Metastability
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_sync1 <= {GPIO_WIDTH{1'b0}};
      data_in_sync2 <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_sync1 <= gpio;
      data_in_sync2 <= data_in_sync1;
    end
  end

  // Interrupt Logic

  // Adjusting Input Data Based on Interrupt Polarity
  assign data_in_pol_adjusted = data_in_sync2 ^ reg_int_pol; // Polarity adjustment

  // Registering Polarity-Adjusted Input Data and Delaying for Edge Detection
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_pol_adjusted_dly <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_pol_adjusted_dly <= data_in_pol_adjusted;
    end
  end

  // Edge Detection Logic for Interrupts
  assign edge_detect = data_in_pol_adjusted & (~data_in_pol_adjusted_dly); // Rising edge detection

  // Selecting Interrupt Type (Edge or Level-Triggered)
  assign raw_int = (reg_int_type & edge_detect) | (~reg_int_type & data_in_pol_adjusted); // Interrupt source

  // Applying Interrupt Enable Mask (global power-down suppresses new interrupts)
  assign int_masked = raw_int & reg_int_en & {GPIO_WIDTH{~reg_pwr_down}}; // Masked interrupts

  // Clear Interrupt Signals (Interrupt State write-1-to-clear at 0x18 and the
  // software-controlled Interrupt Reset Register at 0x24)
  assign clear_interrupt = pwdata[GPIO_WIDTH-1:0] &
                           ({GPIO_WIDTH{write_enable_reg_18}} |
                            {GPIO_WIDTH{write_enable_reg_24}});

  // Updating Interrupt State Register (Corrected Logic)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      reg_int_state <= {GPIO_WIDTH{1'b0}};
    end else begin
      integer i;
      for (i = 0; i < GPIO_WIDTH; i = i + 1) begin
        if (reg_int_type[i]) begin
          // Edge-triggered interrupt
          if (clear_interrupt[i]) begin
            reg_int_state[i] <= 1'b0;
          end else if (int_masked[i]) begin
            reg_int_state[i] <= 1'b1;
          end
        end else begin
          // Level-triggered interrupt
          reg_int_state[i] <= int_masked[i];
        end
      end
    end
  end

  // Connecting Interrupt Outputs
  assign gpio_int = reg_int_state;     // Individual interrupt outputs
  assign comb_int = |reg_int_state;    // Combined interrupt output

endmodule

// APBGlobalHistoryRegister
// APB-accessible 8-bit global history shift register for branch prediction.
//   - predict_history updates on the rising edge of history_shift_valid
//     (modeled as a real clock; misprediction restore has strict priority).
//   - Glitch-free clock gating of pclk: clk_gate_en is latched on the negedge
//     of pclk before being ANDed with pclk (spec: clk_gate_en toggles only on
//     the negedge of pclk).
//   - Zero-wait-state APB slave: pready held high; reserved bits read 0;
//     predict_history is read-only; pslverr asserts on invalid addresses.
module APBGlobalHistoryRegister (
    // Clock & reset
    input  wire        pclk,                 // APB clock
    input  wire        presetn,              // async active-low reset

    // APB interface
    input  wire [9:0]  paddr,                // address bus
    input  wire        pselx,                // slave select
    input  wire        penable,              // enable / access phase
    input  wire        pwrite,               // 1 = write, 0 = read
    input  wire [7:0]  pwdata,               // write data
    output reg         pready,               // ready (zero-wait: held high)
    output reg  [7:0]  prdata,               // read data
    output reg         pslverr,              // slave error (invalid address)

    // History-shift interface (acts as a clock)
    input  wire        history_shift_valid,  // rising edge -> predict_history update

    // Clock-gating enable (toggles only on negedge of pclk)
    input  wire        clk_gate_en,          // assert to gate pclk internally

    // Status & interrupt signals
    output wire        history_full,         // predict_history == 8'hFF
    output wire        history_empty,        // predict_history == 8'h00
    output wire        error_flag,           // invalid-address error
    output wire        interrupt_full,       // driven by history_full
    output wire        interrupt_error       // driven by error_flag
);

    // ------------------------------------------------------------------
    // Register map
    // ------------------------------------------------------------------
    localparam [9:0] ADDR_CONTROL = 10'h000;  // control_register (R/W)
    localparam [9:0] ADDR_TRAIN   = 10'h001;  // train_history    (R/W)
    localparam [9:0] ADDR_PREDICT = 10'h002;  // predict_history  (RO)

    reg [7:0] control_register;  // [0]predict_valid [1]predict_taken
                                 // [2]train_mispredicted [3]train_taken
                                 // [7:4] reserved (read 0)
    reg [7:0] train_history;     // [6:0] history, [7] reserved (read 0)
    reg [7:0] predict_history;   // global history shift register

    // Control-field aliases
    wire predict_valid      = control_register[0];
    wire predict_taken      = control_register[1];
    wire train_mispredicted = control_register[2];
    wire train_taken        = control_register[3];

    // ------------------------------------------------------------------
    // Glitch-free clock gating.
    // clk_gate_en is guaranteed to toggle only on the negedge of pclk, so a
    // level-sensitive latch that captures the enable while pclk is low, ANDed
    // with pclk, yields a glitch-free gated clock (gclk).
    // ------------------------------------------------------------------
    reg clk_en_latch;
    always @(*) begin
        if (!presetn)
            clk_en_latch = 1'b1;          // clock enabled out of reset
        else if (!pclk)
            clk_en_latch = ~clk_gate_en;  // capture enable while pclk is low
    end
    wire gclk = pclk & clk_en_latch;

    // ------------------------------------------------------------------
    // Address decode + read mux (reserved bits read as zero)
    // ------------------------------------------------------------------
    wire addr_valid = (paddr == ADDR_CONTROL) ||
                      (paddr == ADDR_TRAIN)   ||
                      (paddr == ADDR_PREDICT);

    reg [7:0] rdata_mux;
    always @(*) begin
        case (paddr)
            ADDR_CONTROL: rdata_mux = {4'b0000, control_register[3:0]};
            ADDR_TRAIN:   rdata_mux = {1'b0,    train_history[6:0]};
            ADDR_PREDICT: rdata_mux = predict_history;
            default:      rdata_mux = 8'h00;
        endcase
    end

    // ------------------------------------------------------------------
    // APB response: zero wait states (pready always high after reset).
    //   - read data is presented whenever the slave is selected for a read,
    //     so it is valid throughout the ACCESS phase.
    //   - pslverr asserts on invalid addresses while the slave is selected.
    // ------------------------------------------------------------------
    always @(posedge gclk or negedge presetn) begin
        if (!presetn) begin
            pready  <= 1'b0;
            prdata  <= 8'h00;
            pslverr <= 1'b0;
        end else begin
            pready <= 1'b1;
            if (pselx) begin
                pslverr <= ~addr_valid;
                if (!pwrite)
                    prdata <= rdata_mux;
            end else begin
                pslverr <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // CSR writes: commit once in the ACCESS phase (pselx && penable && pwrite).
    // Reserved bits are stored as zero; predict_history is read-only via APB;
    // writes to undecoded addresses update nothing.
    // ------------------------------------------------------------------
    always @(posedge gclk or negedge presetn) begin
        if (!presetn) begin
            control_register <= 8'h00;
            train_history    <= 8'h00;
        end else if (pselx && penable && pwrite) begin
            case (paddr)
                ADDR_CONTROL: control_register <= {4'b0000, pwdata[3:0]};
                ADDR_TRAIN:   train_history    <= {1'b0,    pwdata[6:0]};
                default: ;  // read-only / invalid: ignore
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Global history shift register.
    // history_shift_valid is used as a real clock (updates only on its rising
    // edge). Priority: misprediction restore > normal LSB shift-in.
    //   - normal : shift in predict_taken at the LSB (youngest -> bit[0]).
    //   - mispred: load {train_history[6:0], train_taken} (actual outcome at LSB).
    // ------------------------------------------------------------------
    always @(posedge history_shift_valid or negedge presetn) begin
        if (!presetn)
            predict_history <= 8'h00;
        else if (train_mispredicted)
            predict_history <= {train_history[6:0], train_taken};
        else if (predict_valid)
            predict_history <= {predict_history[6:0], predict_taken};
    end

    // ------------------------------------------------------------------
    // Status & interrupt outputs
    // ------------------------------------------------------------------
    assign history_full    = (predict_history == 8'hFF);
    assign history_empty   = (predict_history == 8'h00);
    assign error_flag      = pslverr;
    assign interrupt_full  = history_full;
    assign interrupt_error = error_flag;

endmodule

module arithmetic_progression_generator #(
    parameter DATA_WIDTH = 16,       // Width of the input data
    parameter SEQUENCE_LENGTH = 10   // Number of terms in the progression
)(
    clk,
    resetn,
    enable,
    start_val,
    step_size,
    out_val,
    done
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------
    // WIDTH_OUT_VAL is sized so the largest possible term never overflows.
    // The maximum term is start_val + (SEQUENCE_LENGTH-1)*step_size, which is
    // bounded by (2^DATA_WIDTH - 1) * SEQUENCE_LENGTH < 2^(DATA_WIDTH+$clog2(SEQUENCE_LENGTH)).
    localparam WIDTH_OUT_VAL = DATA_WIDTH + $clog2(SEQUENCE_LENGTH);

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
    input  logic clk;                          // Clock signal
    input  logic resetn;                       // Active-low reset
    input  logic enable;                       // Enable signal for the generator
    input  logic [DATA_WIDTH-1:0]    start_val; // Start value of the sequence
    input  logic [DATA_WIDTH-1:0]    step_size; // Step size of the sequence
    output logic [WIDTH_OUT_VAL-1:0] out_val;   // Current value of the sequence
    output logic done;                          // High when sequence generation is complete

  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
    logic [WIDTH_OUT_VAL-1:0]           current_val; // Register to hold the current value
    logic [$clog2(SEQUENCE_LENGTH)-1:0] counter;     // Counter to track sequence length

  // ----------------------------------------
  // - Procedural block
  // ----------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_val <= 0;
            counter     <= 0;
            done        <= 1'b0;
        end else if (enable) begin
            if (!done) begin
                // Generate one term per clock. The first term (counter == 0)
                // is start_val; every subsequent term adds step_size. The
                // output therefore appears one clock after enable is asserted.
                if (counter == 0)
                    current_val <= start_val;
                else
                    current_val <= current_val + step_size;

                // Assert done in the very cycle the final (SEQUENCE_LENGTH-th)
                // term is produced, so out_val holds that final value while
                // done is high. Stop advancing the counter so it never exceeds
                // its declared $clog2(SEQUENCE_LENGTH) width.
                if (counter == SEQUENCE_LENGTH - 1)
                    done <= 1'b1;
                else
                    counter <= counter + 1'b1;
            end
            // else: sequence complete -- done stays asserted and out_val holds
            //       the final value until resetn is applied.
        end
        // enable low: pause -- all state (current_val, counter, done) holds.
    end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
    assign out_val = current_val;

endmodule

module arithmetic_progression_generator #(
    parameter DATA_WIDTH = 16,  // Width of the input data
    parameter SEQUENCE_LENGTH = 10 // Number of terms in the progression
)(
    clk,
    resetn,
    enable,
    start_val,
    step_size,
    out_val,
    done
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------

    // Guarded $clog2: avoid the math domain error when SEQUENCE_LENGTH == 0.
    // For SEQUENCE_LENGTH <= 1 the extra width contribution is 0 (matches
    // $clog2(1) == 0), so widths are unchanged for all valid lengths >= 1.
    localparam CLOG2_SEQ_LEN = (SEQUENCE_LENGTH <= 1) ? 0 : $clog2(SEQUENCE_LENGTH);
    localparam WIDTH_OUT_VAL = CLOG2_SEQ_LEN + DATA_WIDTH; // Bit width of out_val to prevent overflow
    localparam COUNTER_WIDTH = (CLOG2_SEQ_LEN == 0) ? 1 : CLOG2_SEQ_LEN; // At least 1 bit wide

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
    input logic clk;                          // Clock signal
    input logic resetn;                       // Active-low reset
    input logic enable;                       // Enable signal for the generator
    input logic [DATA_WIDTH-1:0] start_val;   // Start value of the sequence
    input logic [DATA_WIDTH-1:0] step_size;   // Step size of the sequence
    output logic [WIDTH_OUT_VAL-1:0] out_val; // Current value of the sequence
    output logic done;                        // High when sequence generation is complete


  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
    logic [WIDTH_OUT_VAL-1:0] current_val;  // Register to hold the current value
    logic [COUNTER_WIDTH-1:0] counter;      // Counter to track sequence length

  // ----------------------------------------
  // - Procedural block
  // ----------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_val <= 0;
            counter <= 0;
            done <= 1'b0;
        end else if (enable && (SEQUENCE_LENGTH != 0)) begin
            // When SEQUENCE_LENGTH == 0 there is no sequence to generate:
            // out_val stays at its reset value (0) and done never asserts.
            if (!done) begin
                if (counter == 0) begin
                    current_val <= start_val; // Initialize with start value
                end else begin
                    current_val <= current_val + step_size; // Compute next term
                end

                if (counter < SEQUENCE_LENGTH - 1) begin
                    counter <= counter + 1; // Increment counter
                end else begin
                    done <= 1'b1; // Mark completion
                end
            end
        end
    end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
    assign out_val = current_val;

endmodule

// -----------------------------------------------------------------------------
// axi_register — AXI4-Lite slave register block
//
//   Offset 0x100 : Beat      (R/W, 20-bit counter value, reflected on beat_o)
//   Offset 0x200 : Start     (R/W, 1-bit trigger,        reflected on start_o)
//   Offset 0x300 : Done      (R/W, 1-bit status; hardware-set via done_i,
//                              write-1-to-clear the internal done status)
//   Offset 0x400 : Writeback (R/W, 1-bit trigger,        reflected on writeback_o)
//   Offset 0x500 : ID        (RO,  fixed 32'h0001_0001; writes -> SLVERR)
//
//   * Each channel is an independent one-shot handshake FSM: the *ready is
//     asserted only while the FSM waits for the matching *valid, the address
//     is latched at accept time, and bvalid/rvalid are held until bready/rready.
//   * Full-strobe writes update the register; partial-strobe writes are
//     acknowledged (OKAY) without modifying the register.
//   * Writes to the read-only ID register or to undefined offsets return
//     SLVERR; reads of undefined offsets return SLVERR with zero data.
//   * Async active-low reset: beat_o/start_o/writeback_o and all internal
//     registers are cleared; ready/valid outputs are driven low during reset.
// -----------------------------------------------------------------------------
module axi_register #(
    parameter int ADDR_WIDTH = 32,
    parameter int DATA_WIDTH = 32
) (
    input  logic                      clk_i,
    input  logic                      rst_n_i,

    // Write address channel
    input  logic [ADDR_WIDTH-1:0]     awaddr_i,
    input  logic                      awvalid_i,
    output logic                      awready_o,

    // Write data channel
    input  logic [DATA_WIDTH-1:0]     wdata_i,
    input  logic                      wvalid_i,
    input  logic [(DATA_WIDTH/8)-1:0] wstrb_i,
    output logic                      wready_o,

    // Write response channel
    output logic [1:0]                bresp_o,
    output logic                      bvalid_o,
    input  logic                      bready_i,

    // Read address channel
    input  logic [ADDR_WIDTH-1:0]     araddr_i,
    input  logic                      arvalid_i,
    output logic                      arready_o,

    // Read data channel
    output logic [DATA_WIDTH-1:0]     rdata_o,
    output logic                      rvalid_o,
    output logic [1:0]                rresp_o,
    input  logic                      rready_i,

    // Hardware interface
    input  logic                      done_i,
    output logic [19:0]               beat_o,
    output logic                      start_o,
    output logic                      writeback_o
);

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------
    localparam logic [1:0] RESP_OKAY   = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;

    localparam logic [11:0] ADDR_BEAT      = 12'h100;
    localparam logic [11:0] ADDR_START     = 12'h200;
    localparam logic [11:0] ADDR_DONE      = 12'h300;
    localparam logic [11:0] ADDR_WRITEBACK = 12'h400;
    localparam logic [11:0] ADDR_ID        = 12'h500;

    localparam logic [31:0] ID_VALUE = 32'h0001_0001;

    // Wide read bus (> 32 bits) so every zero-extension below has a strictly
    // positive pad width for any DATA_WIDTH >= 8.
    localparam int RD_W = ((DATA_WIDTH > 32) ? DATA_WIDTH : 32) + 1;

    // -------------------------------------------------------------------------
    // Registers
    // -------------------------------------------------------------------------
    logic [19:0] beat_q;
    logic        start_q;
    logic        done_q;
    logic        writeback_q;

    logic [11:0] awaddr_q;      // latched write address (decode on this)
    logic [1:0]  bresp_q;

    logic [DATA_WIDTH-1:0] rdata_q;
    logic [1:0]            rresp_q;

    // Zero-extended write data so the 20-bit beat slice works for any
    // DATA_WIDTH >= 8.
    logic [DATA_WIDTH+19:0] wdata_ext;
    assign wdata_ext = {20'b0, wdata_i};

    // -------------------------------------------------------------------------
    // Write channel FSM: IDLE (accept AW) -> DATA (accept W) -> RESP (B)
    // -------------------------------------------------------------------------
    typedef enum logic [1:0] {W_IDLE, W_DATA, W_RESP} wstate_e;
    wstate_e wstate_q;

    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            wstate_q    <= W_IDLE;
            awaddr_q    <= '0;
            bresp_q     <= RESP_OKAY;
            beat_q      <= '0;
            start_q     <= 1'b0;
            done_q      <= 1'b0;
            writeback_q <= 1'b0;
        end else begin
            // Hardware sets the done status; a write-1-to-clear in the same
            // cycle (assigned below) has priority.
            if (done_i)
                done_q <= 1'b1;

            case (wstate_q)
                W_IDLE: begin
                    if (awvalid_i) begin        // awready_o is high in W_IDLE
                        awaddr_q <= awaddr_i[11:0];
                        wstate_q <= W_DATA;
                    end
                end

                W_DATA: begin
                    if (wvalid_i) begin         // wready_o is high in W_DATA
                        case (awaddr_q)
                            ADDR_BEAT: begin
                                bresp_q <= RESP_OKAY;
                                if (&wstrb_i)
                                    beat_q <= wdata_ext[19:0];
                            end
                            ADDR_START: begin
                                bresp_q <= RESP_OKAY;
                                if (&wstrb_i)
                                    start_q <= wdata_i[0];
                            end
                            ADDR_DONE: begin
                                bresp_q <= RESP_OKAY;
                                if (&wstrb_i && wdata_i[0])
                                    done_q <= 1'b0;   // W1C beats hardware set
                            end
                            ADDR_WRITEBACK: begin
                                bresp_q <= RESP_OKAY;
                                if (&wstrb_i)
                                    writeback_q <= wdata_i[0];
                            end
                            default: begin
                                // Read-only ID register or undefined offset
                                bresp_q <= RESP_SLVERR;
                            end
                        endcase
                        wstate_q <= W_RESP;
                    end
                end

                W_RESP: begin
                    if (bready_i)               // bvalid_o held until bready_i
                        wstate_q <= W_IDLE;
                end

                default: wstate_q <= W_IDLE;
            endcase
        end
    end

    assign awready_o = rst_n_i && (wstate_q == W_IDLE);
    assign wready_o  = rst_n_i && (wstate_q == W_DATA);
    assign bvalid_o  = (wstate_q == W_RESP);
    assign bresp_o   = bresp_q;

    // -------------------------------------------------------------------------
    // Read channel FSM: IDLE (accept AR, capture data) -> RESP (R)
    // -------------------------------------------------------------------------
    typedef enum logic {R_IDLE, R_RESP} rstate_e;
    rstate_e rstate_q;

    // Combinational read decode of the address being accepted; the result is
    // registered at the accept edge so rdata_o is stable while rvalid_o holds.
    logic [RD_W-1:0] rd_wide;
    logic [1:0]      rresp_n;
    logic [11:0]     araddr_lo;

    assign araddr_lo = araddr_i[11:0];

    always_comb begin
        rd_wide = '0;
        rresp_n = RESP_OKAY;
        case (araddr_lo)
            ADDR_BEAT:      rd_wide = {{(RD_W-20){1'b0}}, beat_q};
            ADDR_START:     rd_wide = {{(RD_W-1){1'b0}}, start_q};
            ADDR_DONE:      rd_wide = {{(RD_W-1){1'b0}}, done_q};
            ADDR_WRITEBACK: rd_wide = {{(RD_W-1){1'b0}}, writeback_q};
            ADDR_ID:        rd_wide = {{(RD_W-32){1'b0}}, ID_VALUE};
            default: begin
                rd_wide = '0;
                rresp_n = RESP_SLVERR;
            end
        endcase
    end

    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            rstate_q <= R_IDLE;
            rdata_q  <= '0;
            rresp_q  <= RESP_OKAY;
        end else begin
            case (rstate_q)
                R_IDLE: begin
                    if (arvalid_i) begin        // arready_o is high in R_IDLE
                        rdata_q  <= rd_wide[DATA_WIDTH-1:0];
                        rresp_q  <= rresp_n;
                        rstate_q <= R_RESP;
                    end
                end

                R_RESP: begin
                    if (rready_i)               // rvalid_o held until rready_i
                        rstate_q <= R_IDLE;
                end

                default: rstate_q <= R_IDLE;
            endcase
        end
    end

    assign arready_o = rst_n_i && (rstate_q == R_IDLE);
    assign rvalid_o  = (rstate_q == R_RESP);
    assign rdata_o   = rdata_q;
    assign rresp_o   = rresp_q;

    // -------------------------------------------------------------------------
    // Hardware-facing outputs
    // -------------------------------------------------------------------------
    assign beat_o      = beat_q;
    assign start_o     = start_q;
    assign writeback_o = writeback_q;

endmodule


