    // Master Write Response Channel (B)
    input           inport_bready_i,
    output          inport_bvalid_o,
    output [1:0]    inport_bresp_o,
    // Master Read Address Channel (AR)
    input           inport_arvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_araddr_i,
    output          inport_arready_o,
    // Master Read Data Channel (R)
    input           inport_rready_i,
    output          inport_rvalid_o,
    output [DATA_WIDTH-1:0]   inport_rdata_o,
    output [1:0]    inport_rresp_o,

    // Default AXI outport
    // Write Address Channel (AW)
    input           outport_awready_i,
    output          outport_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_awaddr_o,
    // Write Data Channel (W)
    input           outport_wready_i,
    output          outport_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_wdata_o,
    output [3:0]    outport_wstrb_o,
    // Write Response Channel (B)
    input           outport_bvalid_i,
    input  [1:0]    outport_bresp_i,
    output          outport_bready_o,
    // Read Address Channel (AR)
    input           outport_arready_i,
    output          outport_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_araddr_o,
    // Read Data Channel (R)
    input           outport_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_rdata_i,
    input  [1:0]    outport_rresp_i,
    output          outport_rready_o,

    // Peripheral 0 interface
    // Write Address Channel (AW)
    input           outport_peripheral0_awready_i,
    output          outport_peripheral0_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_awaddr_o,
    // Write Data Channel (W)
    input           outport_peripheral0_wready_i,
    output          outport_peripheral0_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_peripheral0_wdata_o,
    output [3:0]    outport_peripheral0_wstrb_o,
    // Write Response Channel (B)
    input  [1:0]    outport_peripheral0_bresp_i,
    input           outport_peripheral0_bvalid_i,
    output          outport_peripheral0_bready_o,
    // Read Address Channel (AR)
    input           outport_peripheral0_arready_i,
    output          outport_peripheral0_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_araddr_o,
    // Read Data Channel (R)
    input  [1:0]    outport_peripheral0_rresp_i,
    input           outport_peripheral0_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_peripheral0_rdata_i,
    output          outport_peripheral0_rready_o,

    // Transaction timeout detection
    input  [31:0]   TIMEOUT_THRESHOLD,   // Configurable timeout duration (cycles)
    output          timeout_flag         // Asserted when a transaction times out
);

`define ADDR_SEL_W           1
`define PERIPH0_ADDR         32'h80000000
`define PERIPH0_MASK         32'h80000000

//-----------------------------------------------------------------
// AXI: Read
//-----------------------------------------------------------------
reg [3:0]              read_pending_q;
reg [3:0]              read_pending_r;
reg [`ADDR_SEL_W-1:0]  read_port_q;
reg [`ADDR_SEL_W-1:0]  read_port_r;

always @ *
begin
    read_port_r = `ADDR_SEL_W'b0;
    if ((inport_araddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) read_port_r = `ADDR_SEL_W'd1;
end

wire read_incr_w = (inport_arvalid_i && inport_arready_o);
wire read_decr_w = (inport_rvalid_o && inport_rready_i);

always @ *
begin
    read_pending_r = read_pending_q;

    if (read_incr_w && !read_decr_w)
        read_pending_r = read_pending_r + 4'd1;
    else if (!read_incr_w && read_decr_w)
        read_pending_r = read_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    read_pending_q <= 4'b0;
    read_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    read_pending_q <= read_pending_r;

    // Read command accepted
    if (inport_arvalid_i && inport_arready_o)
    begin
        read_port_q <= read_port_r;
    end
end

wire read_accept_w       = (read_port_q == read_port_r && read_pending_q != 4'hF) || (read_pending_q == 4'h0);

assign outport_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd0);
assign outport_araddr_o  = inport_araddr_i;
assign outport_rready_o  = inport_rready_i;

assign outport_peripheral0_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_araddr_o  = inport_araddr_i;
assign outport_peripheral0_rready_o  = inport_rready_i;

reg        outport_rvalid_r;
reg [DATA_WIDTH-1:0] outport_rdata_r;
reg [1:0]  outport_rresp_r;

always @ *
begin
    case (read_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_rvalid_r = outport_peripheral0_rvalid_i;
        outport_rdata_r  = outport_peripheral0_rdata_i;
        outport_rresp_r  = outport_peripheral0_rresp_i;
    end
    default:
    begin
        outport_rvalid_r = outport_rvalid_i;
        outport_rdata_r  = outport_rdata_i;
        outport_rresp_r  = outport_rresp_i;
    end
    endcase
end

assign inport_rvalid_o  = outport_rvalid_r;
assign inport_rdata_o   = outport_rdata_r;
assign inport_rresp_o   = outport_rresp_r;

reg inport_arready_r;
always @ *
begin
    case (read_port_r)
    `ADDR_SEL_W'd1:
        inport_arready_r = outport_peripheral0_arready_i;
    default:
        inport_arready_r = outport_arready_i;
    endcase
end

assign inport_arready_o = read_accept_w & inport_arready_r;

//-------------------------------------------------------------
// Write Request
//-------------------------------------------------------------
reg awvalid_q;
reg wvalid_q;

wire wr_cmd_accepted_w  = (inport_awvalid_i && inport_awready_o) || awvalid_q;
wire wr_data_accepted_w = (inport_wvalid_i  && inport_wready_o)  || wvalid_q;

always @ (posedge clk_i )
if (rst_i)
    awvalid_q <= 1'b0;
else if (inport_awvalid_i && inport_awready_o && (!wr_data_accepted_w))
    awvalid_q <= 1'b1;
else if (wr_data_accepted_w)
    awvalid_q <= 1'b0;

always @ (posedge clk_i )
if (rst_i)
    wvalid_q <= 1'b0;
else if (inport_wvalid_i && inport_wready_o && !wr_cmd_accepted_w)
    wvalid_q <= 1'b1;
else if (wr_cmd_accepted_w)
    wvalid_q <= 1'b0;

//-----------------------------------------------------------------
// AXI: Write
//-----------------------------------------------------------------
reg [3:0]              write_pending_q;
reg [3:0]              write_pending_r;
reg [`ADDR_SEL_W-1:0]  write_port_q;
reg [`ADDR_SEL_W-1:0]  write_port_r;

always @ *
begin
    if (inport_awvalid_i & ~awvalid_q)
    begin
        write_port_r = `ADDR_SEL_W'b0;
        if ((inport_awaddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) write_port_r = `ADDR_SEL_W'd1;
    end
    else
        write_port_r = write_port_q;
end

wire write_incr_w = (inport_awvalid_i && inport_awready_o);
wire write_decr_w = (inport_bvalid_o  && inport_bready_i);

always @ *
begin
    write_pending_r = write_pending_q;

    if (write_incr_w && !write_decr_w)
        write_pending_r = write_pending_r + 4'd1;
    else if (!write_incr_w && write_decr_w)
        write_pending_r = write_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    write_pending_q <= 4'b0;
    write_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    write_pending_q <= write_pending_r;

    // Write command accepted
    if (inport_awvalid_i && inport_awready_o)
    begin
        write_port_q <= write_port_r;
    end
end

wire write_accept_w      = (write_port_q == write_port_r && write_pending_q != 4'hF) || (write_pending_q == 4'h0);

assign outport_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd0);
assign outport_awaddr_o  = inport_awaddr_i;
assign outport_wvalid_o  = inport_wvalid_i & ~wvalid_q & (inport_awvalid_i || awvalid_q) & (write_port_r == `ADDR_SEL_W'd0);
assign outport_wdata_o   = inport_wdata_i;
assign outport_wstrb_o   = inport_wstrb_i;
assign outport_bready_o  = inport_bready_i;

assign outport_peripheral0_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_awaddr_o  = inport_awaddr_i;
assign outport_peripheral0_wvalid_o  = inport_wvalid_i & ~wvalid_q & ((inport_awvalid_i && write_accept_w) || awvalid_q) & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_wdata_o   = inport_wdata_i;
assign outport_peripheral0_wstrb_o   = inport_wstrb_i;
assign outport_peripheral0_bready_o  = inport_bready_i;

reg        outport_bvalid_r;
reg [1:0]  outport_bresp_r;

always @ *
begin
    case (write_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_bvalid_r = outport_peripheral0_bvalid_i;
        outport_bresp_r  = outport_peripheral0_bresp_i;
    end
    default:
    begin
        outport_bvalid_r = outport_bvalid_i;
        outport_bresp_r  = outport_bresp_i;
    end
    endcase
end

assign inport_bvalid_o  = outport_bvalid_r;
assign inport_bresp_o   = outport_bresp_r;

reg inport_awready_r;
reg inport_wready_r;

always @ *
begin
    case (write_port_r)
    `ADDR_SEL_W'd1:
    begin
        inport_awready_r = outport_peripheral0_awready_i;
        inport_wready_r  = outport_peripheral0_wready_i;
    end
    default:
    begin
        inport_awready_r = outport_awready_i;
        inport_wready_r  = outport_wready_i;
    end
    endcase
end

assign inport_awready_o = write_accept_w & ~awvalid_q & inport_awready_r;
assign inport_wready_o  = write_accept_w & ~wvalid_q & inport_wready_r;

//-----------------------------------------------------------------
// Transaction Timeout Detection
//-----------------------------------------------------------------
// A read transaction is outstanding from when the AR channel is
// presented (or accepted, tracked by read_pending_q) until the R
// response handshake (rvalid && rready) completes.  Likewise a write
// transaction is outstanding from AW until the B response handshake
// (bvalid && bready) completes.  A per-channel timer runs while the
// transaction is outstanding and is cleared on completion or when the
// channel is idle.  When the timer would reach TIMEOUT_THRESHOLD the
// sticky timeout_flag is asserted and held until reset handles it.

wire read_busy_w      = inport_arvalid_i || (read_pending_q  != 4'd0);
wire read_complete_w  = inport_rvalid_o  && inport_rready_i;

wire write_busy_w     = inport_awvalid_i || (write_pending_q != 4'd0);
wire write_complete_w = inport_bvalid_o  && inport_bready_i;

reg  [31:0] read_timeout_cnt_q;
reg  [31:0] write_timeout_cnt_q;

wire [31:0] read_timeout_next_w  = read_timeout_cnt_q  + 32'd1;
wire [31:0] write_timeout_next_w = write_timeout_cnt_q + 32'd1;

// Read timeout timer
always @ (posedge clk_i)
if (rst_i)
    read_timeout_cnt_q <= 32'd0;
else if (read_complete_w || !read_busy_w)
    read_timeout_cnt_q <= 32'd0;
else
    read_timeout_cnt_q <= read_timeout_next_w;

// Write timeout timer
always @ (posedge clk_i)
if (rst_i)
    write_timeout_cnt_q <= 32'd0;
else if (write_complete_w || !write_busy_w)
    write_timeout_cnt_q <= 32'd0;
else
    write_timeout_cnt_q <= write_timeout_next_w;

// Compare the pre-registered next timer value against the threshold so the
// flag asserts exactly as the timer reaches TIMEOUT_THRESHOLD (no off-by-one).
wire read_timeout_w  = read_busy_w  && !read_complete_w  && (read_timeout_next_w  >= TIMEOUT_THRESHOLD);
wire write_timeout_w = write_busy_w && !write_complete_w && (write_timeout_next_w >= TIMEOUT_THRESHOLD);

// Sticky timeout flag: set on a read or write timeout, held until reset.
reg timeout_flag_q;
always @ (posedge clk_i)
if (rst_i)
    timeout_flag_q <= 1'b0;
else if (read_timeout_w || write_timeout_w)
    timeout_flag_q <= 1'b1;

assign timeout_flag = timeout_flag_q;

endmodule

`timescale 1ns / 1ps
//-----------------------------------------------------------------------------
// precision_counter_axi
//
// AXI4-Lite slave managing a high-precision countdown counter.
//
// Register map (byte offsets):
//   0x00  slv_reg_ctl         RW  control (bit0: 1=start, 0=stop). Any write
//                                 to this register clears slv_reg_t to zero.
//   0x0C  ap_done status      RO  returns 1 when the countdown is complete
//                                 (slv_reg_v == 0), otherwise 0.
//   0x10  slv_reg_t           RW  elapsed-time counter; increments by 1 every
//                                 clock while the counter is running and the
//                                 countdown has finished (slv_reg_v == 0).
//   0x20  slv_reg_v           RW  countdown value; decrements by 1 every clock
//                                 while running; a write updates it even while
//                                 the counter is running.
//   0x24  slv_reg_irq_mask    RW  bit0 enables interrupt generation.
//   0x28  slv_reg_irq_thresh  RW  countdown value at which irq is raised.
//
// Responses: 2'b00 (OKAY) for decoded addresses, 2'b10 (SLVERR) for accesses
// outside the implemented map (such writes are ignored). Partial (byte-strobe)
// writes complete with OKAY and update only the strobed bytes.
//-----------------------------------------------------------------------------
module precision_counter_axi #(
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_ADDR_WIDTH = 8
) (
    // clock / reset
    input  wire                                axi_aclk,
    input  wire                                axi_aresetn,

    // AXI write address channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]       axi_awaddr,
    input  wire                                axi_awvalid,
    output wire                                axi_awready,

    // AXI write data channel
    input  wire [C_S_AXI_DATA_WIDTH-1:0]       axi_wdata,
    input  wire [(C_S_AXI_DATA_WIDTH/8)-1:0]   axi_wstrb,
    input  wire                                axi_wvalid,
    output wire                                axi_wready,

    // AXI write response channel
    output wire [1:0]                          axi_bresp,
    output wire                                axi_bvalid,
    input  wire                                axi_bready,

    // AXI read address channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]       axi_araddr,
    input  wire                                axi_arvalid,
    output wire                                axi_arready,

    // AXI read data channel
    output wire [C_S_AXI_DATA_WIDTH-1:0]       axi_rdata,
    output wire [1:0]                          axi_rresp,
    output wire                                axi_rvalid,
    input  wire                                axi_rready,

    // control outputs
    output wire                                axi_ap_done,
    output wire                                irq
);

    //-------------------------------------------------------------------------
    // local parameters
    //-------------------------------------------------------------------------
    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [C_S_AXI_ADDR_WIDTH-1:0] ADDR_CTL        = 'h00;
    localparam [C_S_AXI_ADDR_WIDTH-1:0] ADDR_DONE       = 'h0C;
    localparam [C_S_AXI_ADDR_WIDTH-1:0] ADDR_T          = 'h10;
    localparam [C_S_AXI_ADDR_WIDTH-1:0] ADDR_V          = 'h20;
    localparam [C_S_AXI_ADDR_WIDTH-1:0] ADDR_IRQ_MASK   = 'h24;
    localparam [C_S_AXI_ADDR_WIDTH-1:0] ADDR_IRQ_THRESH = 'h28;

    //-------------------------------------------------------------------------
    // AXI4-Lite interface registers
    //-------------------------------------------------------------------------
    reg                              axi_awready_q;
    reg                              axi_wready_q;
    reg  [1:0]                       axi_bresp_q;
    reg                              axi_bvalid_q;
    reg                              axi_arready_q;
    reg  [C_S_AXI_DATA_WIDTH-1:0]    axi_rdata_q;
    reg  [1:0]                       axi_rresp_q;
    reg                              axi_rvalid_q;
    reg  [C_S_AXI_ADDR_WIDTH-1:0]    axi_awaddr_q;
    reg  [C_S_AXI_ADDR_WIDTH-1:0]    axi_araddr_q;
    reg                              aw_en;

    //-------------------------------------------------------------------------
    // user registers (names per the specification)
    //-------------------------------------------------------------------------
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_ctl;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_t;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_v;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_irq_mask;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_irq_thresh;

    assign axi_awready = axi_awready_q;
    assign axi_wready  = axi_wready_q;
    assign axi_bresp   = axi_bresp_q;
    assign axi_bvalid  = axi_bvalid_q;
    assign axi_arready = axi_arready_q;
    assign axi_rdata   = axi_rdata_q;
    assign axi_rresp   = axi_rresp_q;
    assign axi_rvalid  = axi_rvalid_q;

    //-------------------------------------------------------------------------
    // write address channel: accept the address when both the address and the
    // data are valid; latch the address for the decode.
    //-------------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_awready_q <= 1'b0;
            axi_awaddr_q  <= {C_S_AXI_ADDR_WIDTH{1'b0}};
            aw_en         <= 1'b1;
        end else begin
            if (!axi_awready_q && axi_awvalid && axi_wvalid && aw_en) begin
                axi_awready_q <= 1'b1;
                axi_awaddr_q  <= axi_awaddr;
                aw_en         <= 1'b0;
            end else if (axi_bvalid_q && axi_bready) begin
                axi_awready_q <= 1'b0;
                aw_en         <= 1'b1;
            end else begin
                axi_awready_q <= 1'b0;
            end
        end
    end

    //-------------------------------------------------------------------------
    // write data channel
    //-------------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_wready_q <= 1'b0;
        end else begin
            if (!axi_wready_q && axi_wvalid && axi_awvalid && aw_en)
                axi_wready_q <= 1'b1;
            else
                axi_wready_q <= 1'b0;
        end
    end

    // register write strobe (single cycle)
    wire slv_reg_wren = axi_wready_q && axi_wvalid && axi_awready_q && axi_awvalid;

    // decode of the LATCHED write address
    wire write_addr_hit = (axi_awaddr_q == ADDR_CTL)      ||
                          (axi_awaddr_q == ADDR_T)        ||
                          (axi_awaddr_q == ADDR_V)        ||
                          (axi_awaddr_q == ADDR_IRQ_MASK) ||
                          (axi_awaddr_q == ADDR_IRQ_THRESH);

    //-------------------------------------------------------------------------
    // control / mask / threshold registers (byte-strobed writes)
    //-------------------------------------------------------------------------
    integer byte_index_c;
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            slv_reg_ctl        <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_irq_mask   <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_irq_thresh <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else if (slv_reg_wren) begin
            case (axi_awaddr_q)
                ADDR_CTL: begin
                    for (byte_index_c = 0; byte_index_c < C_S_AXI_DATA_WIDTH/8; byte_index_c = byte_index_c + 1)
                        if (axi_wstrb[byte_index_c])
                            slv_reg_ctl[byte_index_c*8 +: 8] <= axi_wdata[byte_index_c*8 +: 8];
                end
                ADDR_IRQ_MASK: begin
                    for (byte_index_c = 0; byte_index_c < C_S_AXI_DATA_WIDTH/8; byte_index_c = byte_index_c + 1)
                        if (axi_wstrb[byte_index_c])
                            slv_reg_irq_mask[byte_index_c*8 +: 8] <= axi_wdata[byte_index_c*8 +: 8];
                end
                ADDR_IRQ_THRESH: begin
                    for (byte_index_c = 0; byte_index_c < C_S_AXI_DATA_WIDTH/8; byte_index_c = byte_index_c + 1)
                        if (axi_wstrb[byte_index_c])
                            slv_reg_irq_thresh[byte_index_c*8 +: 8] <= axi_wdata[byte_index_c*8 +: 8];
                end
                default: ; // undefined addresses are ignored
            endcase
        end
    end

    //-------------------------------------------------------------------------
    // countdown register slv_reg_v:
    //  - a software write updates it (even while the counter is running)
    //  - while running (slv_reg_ctl[0]) it decrements by 1 each clock until 0
    //  - when stopped it retains its current value
    //-------------------------------------------------------------------------
    integer byte_index_v;
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            slv_reg_v <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else if (slv_reg_wren && (axi_awaddr_q == ADDR_V)) begin
            for (byte_index_v = 0; byte_index_v < C_S_AXI_DATA_WIDTH/8; byte_index_v = byte_index_v + 1)
                if (axi_wstrb[byte_index_v])
                    slv_reg_v[byte_index_v*8 +: 8] <= axi_wdata[byte_index_v*8 +: 8];
        end else if (slv_reg_ctl[0] && (slv_reg_v != {C_S_AXI_DATA_WIDTH{1'b0}})) begin
            slv_reg_v <= slv_reg_v - 1'b1;
        end
    end

    //-------------------------------------------------------------------------
    // elapsed time register slv_reg_t:
    //  - any write to the control register clears it to zero
    //  - a software write to 0x10 updates it
    //  - while running and the countdown is finished (slv_reg_v == 0) it
    //    increments by 1 every clock cycle
    //-------------------------------------------------------------------------
    integer byte_index_t;
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            slv_reg_t <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else if (slv_reg_wren && (axi_awaddr_q == ADDR_CTL)) begin
            slv_reg_t <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else if (slv_reg_wren && (axi_awaddr_q == ADDR_T)) begin
            for (byte_index_t = 0; byte_index_t < C_S_AXI_DATA_WIDTH/8; byte_index_t = byte_index_t + 1)
                if (axi_wstrb[byte_index_t])
                    slv_reg_t[byte_index_t*8 +: 8] <= axi_wdata[byte_index_t*8 +: 8];
        end else if (slv_reg_ctl[0] && (slv_reg_v == {C_S_AXI_DATA_WIDTH{1'b0}})) begin
            slv_reg_t <= slv_reg_t + 1'b1;
        end
    end

    //-------------------------------------------------------------------------
    // write response channel: OKAY for decoded addresses, SLVERR otherwise;
    // bvalid is held until the master acknowledges with bready.
    //-------------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_bvalid_q <= 1'b0;
            axi_bresp_q  <= RESP_OKAY;
        end else begin
            if (slv_reg_wren && !axi_bvalid_q) begin
                axi_bvalid_q <= 1'b1;
                axi_bresp_q  <= write_addr_hit ? RESP_OKAY : RESP_SLVERR;
            end else if (axi_bready && axi_bvalid_q) begin
                axi_bvalid_q <= 1'b0;
            end
        end
    end

    //-------------------------------------------------------------------------
    // read address channel: accept and latch the read address.
    //-------------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_arready_q <= 1'b0;
            axi_araddr_q  <= {C_S_AXI_ADDR_WIDTH{1'b0}};
        end else begin
            if (!axi_arready_q && axi_arvalid) begin
                axi_arready_q <= 1'b1;
                axi_araddr_q  <= axi_araddr;
            end else begin
                axi_arready_q <= 1'b0;
            end
        end
    end

    wire slv_reg_rden = axi_arready_q && axi_arvalid && !axi_rvalid_q;

    // decode of the LATCHED read address
    wire read_addr_hit = (axi_araddr_q == ADDR_CTL)      ||
                         (axi_araddr_q == ADDR_DONE)     ||
                         (axi_araddr_q == ADDR_T)        ||
                         (axi_araddr_q == ADDR_V)        ||
                         (axi_araddr_q == ADDR_IRQ_MASK) ||
                         (axi_araddr_q == ADDR_IRQ_THRESH);

    reg [C_S_AXI_DATA_WIDTH-1:0] reg_data_out;
    always @(*) begin
        case (axi_araddr_q)
            ADDR_CTL:        reg_data_out = slv_reg_ctl;
            ADDR_DONE:       reg_data_out = {{(C_S_AXI_DATA_WIDTH-1){1'b0}}, axi_ap_done};
            ADDR_T:          reg_data_out = slv_reg_t;
            ADDR_V:          reg_data_out = slv_reg_v;
            ADDR_IRQ_MASK:   reg_data_out = slv_reg_irq_mask;
            ADDR_IRQ_THRESH: reg_data_out = slv_reg_irq_thresh;
            default:         reg_data_out = {C_S_AXI_DATA_WIDTH{1'b0}};
        endcase
    end

    //-------------------------------------------------------------------------
    // read data channel: rvalid/rdata are held until the master acknowledges
    // with rready; SLVERR (and zero data) for undecoded addresses.
    //-------------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_rvalid_q <= 1'b0;
            axi_rresp_q  <= RESP_OKAY;
            axi_rdata_q  <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else begin
            if (slv_reg_rden) begin
                axi_rvalid_q <= 1'b1;
                axi_rresp_q  <= read_addr_hit ? RESP_OKAY : RESP_SLVERR;
                axi_rdata_q  <= read_addr_hit ? reg_data_out : {C_S_AXI_DATA_WIDTH{1'b0}};
            end else if (axi_rvalid_q && axi_rready) begin
                axi_rvalid_q <= 1'b0;
            end
        end
    end

    //-------------------------------------------------------------------------
    // control outputs
    //-------------------------------------------------------------------------
    // countdown complete when the countdown value has reached zero
    assign axi_ap_done = (slv_reg_v == {C_S_AXI_DATA_WIDTH{1'b0}});

    // interrupt: asserted while the counter is running, interrupts are enabled
    // and the countdown value matches the threshold; automatically cleared
    // when the countdown stops, the threshold condition is no longer met, or
    // reset is asserted.
    assign irq = slv_reg_ctl[0] && slv_reg_irq_mask[0] &&
                 (slv_reg_v == slv_reg_irq_thresh);

endmodule

`timescale 1ps / 1ps

module axis_image_border_gen #(
    parameter IMG_WIDTH  = 336,               // Image width (X resolution)
    parameter IMG_HEIGHT = 256,              // Image height (Y resolution)
    parameter BORDER_COLOR = 16'hFFFF,       // Border pixel value
    parameter DATA_MASK    = 16'h0000        // Mask for input pixels
)(
    input  wire            clk,              // AXI clock
    input  wire            resetn,           // Active-low reset

    // AXI Stream input interface
    input  wire [15:0]     s_axis_tdata,     // Input stream data
    input  wire            s_axis_tvalid,    // Input data valid
    output wire            s_axis_tready,    // Output ready
    input  wire            s_axis_tlast,     // Input last signal
    input  wire            s_axis_tuser,     // Frame start signal

    // AXI Stream output interface
    output wire [15:0]     m_axis_tdata,     // Output stream data
    output wire            m_axis_tvalid,    // Output data valid
    input  wire            m_axis_tready,    // Input ready
    output wire            m_axis_tlast,     // Output last signal
    output wire            m_axis_tuser      // Frame start signal
);

    // State definitions
    localparam [2:0] ST_IDLE        = 3'd0;  // Wait for a new frame start (s_axis_tuser)
    localparam [2:0] ST_ROW_FIRST   = 3'd1;  // Emit the first (top border) row
    localparam [2:0] ST_PROCESS_ROW = 3'd2;  // Emit middle rows: left/right border + image data
    localparam [2:0] ST_BORDER_ROW  = 3'd3;  // Emit the bottom border row
    localparam [2:0] ST_ROW_LAST    = 3'd4;  // Frame complete, return to idle

    // Output frame geometry: input image plus a one-pixel border ring
    localparam integer OUT_WIDTH  = IMG_WIDTH  + 2;
    localparam integer OUT_HEIGHT = IMG_HEIGHT + 2;
    localparam integer FRAME_PIX  = (IMG_WIDTH * IMG_HEIGHT < 1) ? 1
                                                                 : IMG_WIDTH * IMG_HEIGHT;

    // State and Counter Registers
    reg [2:0] state, next_state;
    reg [15:0] x_count, y_count;
    reg border_valid;

    // Internal Control Signals
    wire is_top_row     = (y_count == 16'd0);
    wire is_bottom_row  = (y_count == IMG_HEIGHT + 1);
    wire is_left_border  = (x_count == 16'd0);
    wire is_right_border = (x_count == IMG_WIDTH + 1);
    wire is_border_pixel = (is_top_row || is_bottom_row || is_left_border || is_right_border);

    // ------------------------------------------------------------------
    // Input (receive) side: store-and-forward full-frame buffer.
    // The input pixel count (W*H) differs from the output pixel count
    // ((W+2)*(H+2)), so input and output are decoupled through a frame
    // buffer: a RECEIVE phase fills the buffer, then the FSM emits the
    // bordered frame.
    // ------------------------------------------------------------------
    reg [15:0] frame_buf [0:FRAME_PIX-1];
    reg        rx_active;                     // Currently capturing a frame
    reg        frame_done;                    // Full frame stored; emitting
    reg [31:0] rx_count;                      // Write index into frame_buf

    wire s_beat    = s_axis_tvalid && s_axis_tready;
    wire rx_take   = s_beat && (rx_active || s_axis_tuser);
    wire emit_done = (state == ST_ROW_LAST);

    // Ready to accept input whenever a full frame is not being emitted
    assign s_axis_tready = resetn && !frame_done;

    // Frame buffer write
    always @(posedge clk) begin
        if (rx_take)
            frame_buf[rx_count] <= s_axis_tdata;
    end

    // Receive control
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            rx_active  <= 1'b0;
            frame_done <= 1'b0;
            rx_count   <= 32'd0;
        end else begin
            if (rx_take) begin
                if (rx_count == FRAME_PIX - 1) begin
                    rx_active  <= 1'b0;
                    frame_done <= 1'b1;
                    rx_count   <= 32'd0;
                end else begin
                    rx_active  <= 1'b1;
                    rx_count   <= rx_count + 32'd1;
                end
            end
            if (emit_done)
                frame_done <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // FSM and Counter Logic (output / emit side)
    // ------------------------------------------------------------------
    wire m_beat  = m_axis_tvalid && m_axis_tready;
    wire row_end = (x_count == OUT_WIDTH - 1);

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            // Reset the variables
            state        <= ST_IDLE;
            x_count      <= 16'd0;
            y_count      <= 16'd0;
            border_valid <= 1'b0;
        end else begin
            state        <= next_state;
            border_valid <= m_axis_tvalid && is_border_pixel;
            case (state)
                ST_IDLE: begin
                    x_count <= 16'd0;
                    y_count <= 16'd0;
                end
                ST_ROW_FIRST,
                ST_PROCESS_ROW,
                ST_BORDER_ROW: begin
                    // Advance output position only on an accepted beat
                    if (m_beat) begin
                        if (row_end) begin
                            x_count <= 16'd0;
                            y_count <= y_count + 16'd1;
                        end else begin
                            x_count <= x_count + 16'd1;
                        end
                    end
                end
                ST_ROW_LAST: begin
                    x_count <= 16'd0;
                    y_count <= 16'd0;
                end
                default: begin
                    x_count <= 16'd0;
                    y_count <= 16'd0;
                end
            endcase
        end
    end

    // FSM next-state logic
    always @* begin
        next_state = state;
        case (state)
            ST_IDLE: begin
                if (frame_done)
                    next_state = ST_ROW_FIRST;
            end
            ST_ROW_FIRST: begin
                if (m_beat && row_end)
                    next_state = (IMG_HEIGHT == 0) ? ST_BORDER_ROW : ST_PROCESS_ROW;
            end
            ST_PROCESS_ROW: begin
                if (m_beat && row_end && (y_count == IMG_HEIGHT))
                    next_state = ST_BORDER_ROW;
            end
            ST_BORDER_ROW: begin
                if (m_beat && row_end)
                    next_state = ST_ROW_LAST;
            end
            ST_ROW_LAST: begin
                next_state = ST_IDLE;
            end
            default: begin
                next_state = ST_IDLE;
            end
        endcase
    end

    // ------------------------------------------------------------------
    // Buffer read: inner pixel at (x_count-1, y_count-1)
    // ------------------------------------------------------------------
    wire [15:0] ix = x_count - 16'd1;
    wire [15:0] iy = y_count - 16'd1;
    wire [31:0] rd_index = is_border_pixel ? 32'd0 : (iy * IMG_WIDTH + ix);
    wire [15:0] inner_pixel = frame_buf[rd_index];

    // ------------------------------------------------------------------
    // AXI Stream output signals
    // ------------------------------------------------------------------
    assign m_axis_tvalid = (state == ST_ROW_FIRST) ||
                           (state == ST_PROCESS_ROW) ||
                           (state == ST_BORDER_ROW);
    assign m_axis_tdata  = is_border_pixel ? BORDER_COLOR[15:0]
                                           : (inner_pixel | DATA_MASK[15:0]);
    assign m_axis_tlast  = m_axis_tvalid && row_end;
    assign m_axis_tuser  = m_axis_tvalid && (state == ST_ROW_FIRST) && (x_count == 16'd0);

endmodule


