module barrel_shifter #(
    parameter data_width = 16,
    parameter shift_bits_width = 4
)(
    input [data_width-1:0] data_in,
    input [shift_bits_width-1:0] shift_bits,
    input [2:0] mode,
    input left_right,
    input [data_width-1:0] mask,
    input enable,
    input enable_parity,
    input [data_width-1:0] condition,
    input [1:0] bit_op_type,
    output reg [data_width-1:0] data_out,
    output reg parity_out,
    output reg [1:0] error
);

// Error encoding:
//   2'b00 : No Error
//   2'b01 : Invalid Mode / Invalid Operation
//   2'b10 : Out-of-Range Shift
//   2'b11 : Reserved for future use

always @(*) begin
    if (!enable) begin
        data_out = data_out;
        error = 2'b00;
        parity_out = 0;
    end else begin
        error = 2'b00;
        case (mode)
            3'b000: begin
                if (shift_bits >= data_width) begin
                    error = 2'b10;
                    data_out = {data_width{1'b0}};
                end else if (left_right) begin
                    data_out = data_in << shift_bits;
                end else begin
                    data_out = data_in >> shift_bits;
                end
            end
            3'b001: begin
                if (shift_bits >= data_width) begin
                    error = 2'b10;
                    data_out = {data_width{1'b0}};
                end else if (left_right) begin
                    data_out = data_in << shift_bits;
                end else begin
                    data_out = $signed(data_in) >>> shift_bits;
                end
            end
            3'b010: begin
                if (shift_bits >= data_width) begin
                    error = 2'b10;
                    data_out = {data_width{1'b0}};
                end else if (left_right) begin
                    data_out = (data_in << shift_bits) | (data_in >> (data_width - shift_bits));
                end else begin
                    data_out = (data_in >> shift_bits) | (data_in << (data_width - shift_bits));
                end
            end
            3'b011: begin
                if (shift_bits >= data_width) begin
                    error = 2'b10;
                    data_out = {data_width{1'b0}};
                end else if (left_right) begin
                    data_out = (data_in << shift_bits) & mask;
                end else begin
                    data_out = (data_in >> shift_bits) & mask;
                end
            end
            3'b100: begin
                if (left_right) begin
                    data_out = data_in + shift_bits;
                end else begin
                    data_out = data_in - shift_bits;
                end
            end
            3'b101: begin
                data_out = 0;
                for (int i = data_width-1; i >= 0; i = i - 1) begin
                    if (data_in[i] == 1 && data_out == 0) begin
                        data_out = i;
                    end
                end
            end
            3'b110: begin
                // Reserved mode: invalid for the current configuration
                data_out = {data_width{1'b0}};
                error = 2'b01;
            end
            3'b111: begin
                // Conditional bit manipulation mode
                case (bit_op_type)
                    2'b00: data_out = data_in ^ condition;   // Toggle
                    2'b01: data_out = data_in | condition;   // Set
                    2'b10: data_out = data_in & ~condition;  // Clear
                    default: begin                            // Invalid operation type
                        data_out = {data_width{1'b0}};
                        error = 2'b01;
                    end
                endcase
            end
            default: begin
                data_out = {data_width{1'b0}};
                error = 2'b01;
            end
        endcase
    end

    if (enable_parity) begin
        parity_out = ^data_out;
    end else begin
        parity_out = 0;
    end
end

endmodule

module binary_search_tree_sort #(
    parameter DATA_WIDTH = 32,
    parameter ARRAY_SIZE = 8
) (
    input clk,
    input reset,
    input [ARRAY_SIZE*DATA_WIDTH-1:0] data_in, // Input data to be sorted
    input start,
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] sorted_out, // Sorted output
    output reg done
);

    // Parameters for top-level FSM states
    parameter IDLE = 2'b00, BUILD_TREE = 2'b01, SORT_TREE = 2'b10;

    // Parameters for the BUILD_TREE FSM states
    parameter INIT       = 2'b00, // load next input element / check completion
              CHECK_ROOT = 2'b01, // insert as root, or start traversal at root
              TRAVERSE   = 2'b10, // walk down the tree to find a NULL position
              COMPLETE   = 2'b11; // tree construction complete

    // Parameters for the SORT_TREE FSM states
    parameter S_INIT          = 2'b00, // check root and load it as current_node
              S_TRAVERSE_LEFT = 2'b01, // push nodes while descending left
              S_POP           = 2'b10, // pop a node and store its key as output
              S_RIGHT         = 2'b11; // move to the popped node's right child

    // Pointer width: node-index width + 1 so the all-ones code is a distinct
    // NULL sentinel even for node index 0
    localparam PTR_W = $clog2(ARRAY_SIZE) + 1;

    // Registers for FSM states
    reg [1:0] top_state, build_state, sort_state;

    // BST representation
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys; // Array to store node keys
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child; // Left child pointers
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child; // Right child pointers
    reg [$clog2(ARRAY_SIZE):0] root; // Root node pointer
    reg [$clog2(ARRAY_SIZE):0] next_free_node; // Pointer to the next free node

    // Stack for in-order traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] stack; // Stack for traversal
    reg [$clog2(ARRAY_SIZE):0] sp; // Stack pointer

    // Working registers
    reg [$clog2(ARRAY_SIZE):0] current_node; // Current node being processed
    reg [$clog2(ARRAY_SIZE):0] input_index; // Index for input data
    reg [$clog2(ARRAY_SIZE):0] output_index; // Index for output data
    reg [DATA_WIDTH-1:0] temp_data; // Temporary data register

    // Input array latched when start is accepted: any change on data_in in
    // the middle of the operation is ignored (the earlier value is retained)
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] input_array;

    // Combinational views of the node addressed by current_node / stack top
    wire [PTR_W-1:0]      cur_left  = left_child [current_node*PTR_W +: PTR_W];
    wire [PTR_W-1:0]      cur_right = right_child[current_node*PTR_W +: PTR_W];
    wire [DATA_WIDTH-1:0] cur_key   = keys[current_node*DATA_WIDTH +: DATA_WIDTH];
    wire [PTR_W-1:0]      sp_m1     = sp - 1'b1;
    wire [PTR_W-1:0]      stack_top = stack[sp_m1*PTR_W +: PTR_W];
    wire [DATA_WIDTH-1:0] top_key   = keys[stack_top*DATA_WIDTH +: DATA_WIDTH];

    // Initialize all variables
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            top_state <= IDLE;
            build_state <= INIT;
            sort_state <= S_INIT;

            root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
            next_free_node <= 0;
            sp <= 0;
            input_index <= 0;
            output_index <= 0;
            done <= 0;
            sorted_out <= 0;
            current_node <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            temp_data <= 0;
            input_array <= 0;

            // Clear tree arrays
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            case (top_state)
                IDLE: begin
                    done <= 0;
                    sorted_out <= 0;
                    input_index <= 0;
                    output_index <= 0;
                    root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
                    next_free_node <= 0;
                    sp <= 0;
                    for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                        keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                        left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                    end
                    if (start) begin
                        // Load input data into input array
                        input_array <= data_in;
                        top_state <= BUILD_TREE;
                        build_state <= INIT;
                    end
                end

                BUILD_TREE: begin
                    case (build_state)

                        INIT: begin
                            // One cycle: read the next number from the input
                            // array, or detect that all elements are inserted
                            if (input_index < ARRAY_SIZE) begin
                                temp_data <= input_array[input_index*DATA_WIDTH +: DATA_WIDTH];
                                build_state <= CHECK_ROOT;
                            end else begin
                                build_state <= COMPLETE;
                            end
                        end

                        CHECK_ROOT: begin
                            if (root == {PTR_W{1'b1}}) begin
                                // Tree empty: insert temp_data as the root
                                keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                root <= next_free_node;
                                next_free_node <= next_free_node + 1'b1;
                                input_index <= input_index + 1'b1;
                                build_state <= INIT;
                            end else begin
                                // Root exists: start traversal at the root
                                current_node <= root;
                                build_state <= TRAVERSE;
                            end
                        end

                        TRAVERSE: begin
                            // One cycle per level: compare and either insert
                            // at a NULL child or descend to the child
                            if (temp_data > cur_key) begin
                                if (cur_right == {PTR_W{1'b1}}) begin
                                    // Insert temp_data as right child
                                    right_child[current_node*PTR_W +: PTR_W] <= next_free_node;
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index <= input_index + 1'b1;
                                    build_state <= INIT;
                                end else begin
                                    current_node <= cur_right;
                                end
                            end else begin
                                if (cur_left == {PTR_W{1'b1}}) begin
                                    // Insert temp_data as left child
                                    left_child[current_node*PTR_W +: PTR_W] <= next_free_node;
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index <= input_index + 1'b1;
                                    build_state <= INIT;
                                end else begin
                                    current_node <= cur_left;
                                end
                            end
                        end

                        COMPLETE: begin
                            // Tree construction complete
                            top_state <= SORT_TREE;
                            sort_state <= S_INIT;
                        end

                    endcase
                end

                SORT_TREE: begin
                    case (sort_state)

                        S_INIT: begin
                            // One cycle: check root is not NULL and assign it
                            if (root != {PTR_W{1'b1}}) begin
                                current_node <= root;
                                sort_state <= S_TRAVERSE_LEFT;
                            end else begin
                                // Empty tree: nothing to output
                                done <= 1'b1;
                                top_state <= IDLE;
                            end
                        end

                        S_TRAVERSE_LEFT: begin
                            // Descend the left subtree, pushing each node;
                            // one extra cycle when left child is NULL to
                            // proceed to the popping state
                            if (current_node != {PTR_W{1'b1}}) begin
                                stack[sp*PTR_W +: PTR_W] <= current_node;
                                sp <= sp + 1'b1;
                                current_node <= cur_left;
                            end else begin
                                sort_state <= S_POP;
                            end
                        end

                        S_POP: begin
                            if (sp == 0) begin
                                // All nodes traversed: set the outputs
                                done <= 1'b1;
                                top_state <= IDLE;
                            end else begin
                                // Pop the stack and store the key as output
                                sorted_out[output_index*DATA_WIDTH +: DATA_WIDTH] <= top_key;
                                output_index <= output_index + 1'b1;
                                current_node <= stack_top;
                                sp <= sp_m1;
                                sort_state <= S_RIGHT;
                            end
                        end

                        S_RIGHT: begin
                            // Assign the right child of the popped node; the
                            // next S_TRAVERSE_LEFT cycle checks if it exists
                            current_node <= cur_right;
                            sort_state <= S_TRAVERSE_LEFT;
                        end

                    endcase
                end
            endcase
        end
    end
endmodule

module bus_arbiter (
    input wire reset,
    input wire clk,
    input wire req1,
    input wire req2,
    output reg grant1,
    output reg grant2
);
    // State encoding using localparam
    localparam IDLE    = 3'b000,
               GRANT_1 = 3'b001,
               GRANT_2 = 3'b010,
               CLEAR   = 3'b011;

    // State registers
    reg [2:0] state;
    reg [2:0] next_state;

    // Sequential logic for state transition (asynchronous, active-high reset)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic for next state
    always @(*) begin
        // Default: hold current state
        next_state = state;

        case (state)
            IDLE: begin
                // req2 is prioritized when both requests are asserted
                if (req2)
                    next_state = GRANT_2;
                else if (req1)
                    next_state = GRANT_1;
                else
                    next_state = IDLE;
            end

            GRANT_1: begin
                // Both asserted simultaneously -> req2 preempts (req2 priority)
                if (req1 && req2)
                    next_state = GRANT_2;
                // req1 still asserted alone -> keep granting Master 1
                else if (req1)
                    next_state = GRANT_1;
                // req1 deasserted -> clear grants first, then (from CLEAR)
                // return to IDLE or serve another pending request
                else
                    next_state = CLEAR;
            end

            GRANT_2: begin
                // req2 is the highest priority: hold while it stays asserted
                if (req2)
                    next_state = GRANT_2;
                // req2 (the served request) deasserted -> clear grants first
                else
                    next_state = CLEAR;
            end

            CLEAR: begin
                // Re-arbitrate after clearing grants (req2 prioritized), or
                // return to IDLE when nothing is pending
                if (req2)
                    next_state = GRANT_2;
                else if (req1)
                    next_state = GRANT_1;
                else
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output logic: grant1/grant2 are driven (registered) based on the next
    // state of the FSM. Asynchronous reset deasserts both grants.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            grant1 <= 1'b0;
            grant2 <= 1'b0;
        end else begin
            case (next_state)
                GRANT_1: begin
                    grant1 <= 1'b1;
                    grant2 <= 1'b0;
                end
                GRANT_2: begin
                    grant1 <= 1'b0;
                    grant2 <= 1'b1;
                end
                default: begin // IDLE, CLEAR -> no grants asserted
                    grant1 <= 1'b0;
                    grant2 <= 1'b0;
                end
            endcase
        end
    end

endmodule

module pseudo_lru_tree_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam integer NBITS_TREE = NWAYS - 1;
    localparam integer TREE_DEPTH = $clog2(NWAYS);

    // Recency array to track next way to be replaced (level-order tree per set)
    reg [NBITS_TREE-1:0] recency [NINDEXES-1:0];

    wire [NBITS_TREE-1:0]    recency_updated;
    wire [$clog2(NWAYS)-1:0] pseudo_lru_slot;

    integer i;

    // Sequential logic for reset and recency updates
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            for (i = 0; i < NINDEXES; i++) begin
                recency[i] <= {NBITS_TREE{1'b0}};
            end
        end else begin
            if (access) begin
                recency[index] <= recency_updated;
            end
        end
    end

    // Way that becomes Most Recently Used (MRU) on this access:
    //  - hit  : the accessed way (way_select)
    //  - miss : the way just selected for replacement (pseudo_lru_slot)
    wire [$clog2(NWAYS)-1:0] mru_way = hit ? way_select : pseudo_lru_slot;

    logic [NBITS_TREE-1:0]    recency_next;
    logic [$clog2(NWAYS)-1:0] mru_pos;
    logic                     mru_bit;
    integer d;

    // Update recency tree: descend along the MRU way's path (MSB = depth 0),
    // pointing every visited node AWAY from the MRU way. Off-path nodes keep
    // their previous value. Node at depth d, position p lives at (2^d - 1) + p.
    always_comb begin
        recency_next = recency[index];
        mru_pos      = '0;
        mru_bit      = 1'b0;
        for (d = 0; d < TREE_DEPTH; d = d + 1) begin
            // Update recency tree for hit / Update tree to mark replaced way as MRU
            mru_bit = mru_way[TREE_DEPTH-1-d];
            recency_next[(2**d - 1) + mru_pos] = ~mru_bit; // point toward LRU side
            mru_pos = (mru_pos << 1) | mru_bit;            // descend to MRU child
        end
    end

    assign recency_updated = recency_next;

    // Select the Pseudo LRU slot
    slot_select_pseudo_lru_tree #(
        .NWAYS (NWAYS)
    ) slot_select_unit (
        .array (recency[index]),
        .index (pseudo_lru_slot)
    );

    assign way_replace = pseudo_lru_slot;

endmodule : pseudo_lru_tree_policy

module slot_select_pseudo_lru_tree #(
    parameter NWAYS = 4
)(
    input [NWAYS-2:0] array,
    output logic [$clog2(NWAYS)-1:0] index
);

    localparam integer MAX_DEPTH = $clog2(NWAYS);

    integer depth;
    logic [$clog2(NWAYS)-1:0] step;
    logic direction;

    // Find the Pseudo LRU way index: follow each stored node bit directly
    // (it points toward the replacement / LRU side). Node at depth 'depth',
    // position 'step' lives at array index (2^depth - 1) + step.
    always_comb begin
        step      = '0;
        direction = 1'b0;
        for (depth = 0; depth < MAX_DEPTH; depth = depth + 1) begin
            direction = array[(2**depth - 1) + step];
            step      = (step << 1) | direction;
        end
        index = step;
    end

endmodule : slot_select_pseudo_lru_tree

module clock_jitter_detection_module #(
    parameter JITTER_THRESHOLD = 5    // Threshold (in clock cycles) for detecting jitter
)(
    input logic clk,               // Input clock
    input logic system_clk,        // Input system clock
    input logic rst,               // Active high reset
    output logic jitter_detected   // Output flag indicating jitter detection
);

    // Internal signals
    logic [31:0] edge_count, edge_count_r;   // Counters to measure time between rising edges
    logic prev_system_clk;                   // To store the previous clock state (rising edge detection)
    logic edge_detected;                     // Flag for detecting rising edges
    logic start_counter;                     // Counting enabled once the first rising edge is seen

    // Power-up determinism: known values before the first reset is applied
    initial begin
        edge_count      = 32'd0;
        edge_count_r    = 32'd0;
        prev_system_clk = 1'b0;
        edge_detected   = 1'b0;
        start_counter   = 1'b0;
        jitter_detected = 1'b0;
    end

    // Rising edge detection logic (detects when clock transitions from 0 to 1)
    always @(posedge clk) begin
        if (rst) begin
            // Initialize counters, edge detection, and jitter detection on reset
            edge_count      <= 32'd0;
            edge_count_r    <= 32'd0;
            prev_system_clk <= 1'b0;
            edge_detected   <= 1'b0;
            start_counter   <= 1'b0;
            jitter_detected <= 1'b0;
        end else begin
            prev_system_clk <= system_clk;

            if (system_clk && !prev_system_clk) begin
                // Rising edge of system_clk observed on this clk edge
                edge_detected <= 1'b1;
                start_counter <= 1'b1;     // start measuring from the first edge

                // Store the just-completed edge-to-edge cycle count for
                // comparison and restart the counter at 1 (the edge cycle
                // itself is the first cycle of the new interval)
                edge_count_r  <= edge_count;
                edge_count    <= 32'd1;

                // Compare the recorded edge timing against JITTER_THRESHOLD.
                // Only a complete edge-to-edge interval participates
                // (start_counter gates out the warm-up before the first edge,
                // when no full interval exists yet). Jitter = the measured
                // interval deviates from JITTER_THRESHOLD by MORE than one
                // clock cycle, in either direction.
                if (start_counter &&
                    ((edge_count > JITTER_THRESHOLD + 1) ||
                     (edge_count + 32'd1 < JITTER_THRESHOLD)))
                    jitter_detected <= 1'b1;
                else
                    jitter_detected <= 1'b0;
            end else begin
                edge_detected   <= 1'b0;
                // jitter_detected is a one-cycle pulse: it resets on the next
                // clock cycle unless additional jitter is identified
                jitter_detected <= 1'b0;

                // Keep counting clk cycles between rising edges (saturate so a
                // stalled system_clk can never wrap the counter)
                if (start_counter && (edge_count != 32'hFFFF_FFFF))
                    edge_count <= edge_count + 32'd1;
            end
        end
    end

endmodule

module compression_engine (
  input   logic        clk,
  input   logic        reset,
  input   logic [23:0] num_i,
  output  logic [11:0] mantissa_o,
  output  logic [3:0]  exponent_o
);

  // --------------------------------------------------------
  // Internal wires and registers
  // --------------------------------------------------------
  logic [23:12] exp_oh;         // One-hot encoded exponent
  logic [3:0]   exp_bin;        // Binary exponent
  logic [3:0]   exponent;       // Adjusted exponent
  logic [11:0]  mantissa;       // Mantissa

  // --------------------------------------------------------
  // One-Hot Encoding of the Exponent
  // --------------------------------------------------------
  assign exp_oh[23] = num_i[23];

  // One-hot encoding of the most significant set bit (bits 22 down to 12):
  // exp_oh[i] = num_i[i] & ~|num_i[23:i+1]
  genvar gi;
  generate
    for (gi = 12; gi <= 22; gi = gi + 1) begin : g_exp_oh
      assign exp_oh[gi] = num_i[gi] & ~(|num_i[23:gi+1]);
    end
  endgenerate

  // Use the `onehot_to_bin` module to convert one-hot to binary exponent
  onehot_to_bin #(
    .ONE_HOT_W(12),
    .BIN_W(4)
  ) exp_oh_bin (
    .oh_vec_i(exp_oh),
    .bin_vec_o(exp_bin)
  );

  assign exponent = (|exp_oh) ? exp_bin + 4'h1 : 4'h0;

  // --------------------------------------------------------
  // Mantissa Extraction Logic
  // --------------------------------------------------------
  // If exponent == 0, the value fits in the lower 12 bits: mantissa = num_i[11:0].
  // Otherwise the first set bit sits at position (exponent + 11); the mantissa
  // is the 12 bits immediately BELOW that leading one (hidden-bit convention,
  // as pinned by the worked example table: 24'hFFC01D -> 12'hFF8, 4'hC, and the
  // reconstruction {1'b1, mantissa} << (exponent-1) == 24'hFFC000).
  logic [23:0] num_shifted;
  assign num_shifted = num_i >> (exponent - 4'd1);
  assign mantissa    = (exponent == 4'd0) ? num_i[11:0] : num_shifted[11:0];

  // --------------------------------------------------------
  // Output assignments
  // --------------------------------------------------------
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      exponent_o <= 4'd0;
      mantissa_o <= 12'd0;
    end else begin
      exponent_o <= exponent;
      mantissa_o <= mantissa;
    end
  end

endmodule

module onehot_to_bin #(
  parameter ONE_HOT_W = 32,  // Width of the one-hot input
  parameter BIN_W     = 5    // Width of the binary output
)(
  input   wire [ONE_HOT_W-1:0]  oh_vec_i,  // One-hot encoded input
  output  logic [BIN_W-1:0]     bin_vec_o  // Binary encoded output
);

  integer i;

  // Priority encoding: OR together the index of every set bit.
  // For a one-hot input this yields the zero-based position of the set bit;
  // for an all-zero input it yields 0.
  always @(*) begin
    bin_vec_o = {BIN_W{1'b0}};
    for (i = 0; i < ONE_HOT_W; i = i + 1) begin
      if (oh_vec_i[i])
        bin_vec_o = bin_vec_o | i[BIN_W-1:0];
    end
  end

endmodule

//------------------------------------------------------------------------------
// enhanced_fsm_signal_processor
//
// FSM-managed signal processor:
//   IDLE(00) -> PROCESS(01) -> READY(10) -> IDLE, with FAULT(11) override.
//
// PROCESS concatenates the six 5-bit input vectors (i_vector_1 = MSBs) into a
// 30-bit bus, appends two 1'b1 bits at the LSB to form a 32-bit bus, and splits
// it into four 8-bit output vectors (o_vector_1 = MSB byte ... o_vector_4 = LSB
// byte).
//
// Precedence: i_rst_n (async, active-low) > i_fault > normal flow.
// i_fault takes precedence over every input except i_clk / i_rst_n.
// All outputs are registered (synchronous to i_clk):
//   - o_ready  is high exactly while o_fsm_status == READY
//   - o_error  is high exactly while o_fsm_status == FAULT
//   - o_vector_* hold the last computed split, cleared by reset / FAULT.
//------------------------------------------------------------------------------

module enhanced_fsm_signal_processor (
    input  wire       i_clk,
    input  wire       i_rst_n,
    input  wire       i_enable,
    input  wire       i_clear,
    input  wire       i_ack,
    input  wire       i_fault,
    input  wire [4:0] i_vector_1,
    input  wire [4:0] i_vector_2,
    input  wire [4:0] i_vector_3,
    input  wire [4:0] i_vector_4,
    input  wire [4:0] i_vector_5,
    input  wire [4:0] i_vector_6,
    output reg        o_ready,
    output reg        o_error,
    output reg  [1:0] o_fsm_status,
    output reg  [7:0] o_vector_1,
    output reg  [7:0] o_vector_2,
    output reg  [7:0] o_vector_3,
    output reg  [7:0] o_vector_4
);

    // FSM state encoding (fixed by the spec's o_fsm_status encoding).
    localparam [1:0] IDLE    = 2'b00;
    localparam [1:0] PROCESS = 2'b01;
    localparam [1:0] READY   = 2'b10;
    localparam [1:0] FAULT   = 2'b11;

    // 30-bit concatenation of the six 5-bit inputs, 2'b11 appended at the LSB
    // -> {v1, v2, v3, v4, v5, v6, 2'b11} (MSB .. LSB).
    wire [31:0] concat_bus = {i_vector_1, i_vector_2, i_vector_3,
                              i_vector_4, i_vector_5, i_vector_6, 2'b11};

    // o_fsm_status doubles as the state register (it *is* the current state).
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            // Reset: FSM -> IDLE, clear all outputs, reset fault.
            o_fsm_status <= IDLE;
            o_ready      <= 1'b0;
            o_error      <= 1'b0;
            o_vector_1   <= 8'd0;
            o_vector_2   <= 8'd0;
            o_vector_3   <= 8'd0;
            o_vector_4   <= 8'd0;
        end
        else if (i_fault) begin
            // Fault handling takes precedence over every other input.
            // Enter/stay in FAULT, assert error, force outputs to default.
            o_fsm_status <= FAULT;
            o_error      <= 1'b1;
            o_ready      <= 1'b0;
            o_vector_1   <= 8'd0;
            o_vector_2   <= 8'd0;
            o_vector_3   <= 8'd0;
            o_vector_4   <= 8'd0;
        end
        else begin
            case (o_fsm_status)
                IDLE: begin
                    // Default state: wait for enable; data outputs hold.
                    o_ready <= 1'b0;
                    o_error <= 1'b0;
                    if (i_enable)
                        o_fsm_status <= PROCESS;
                    else
                        o_fsm_status <= IDLE;
                end

                PROCESS: begin
                    // Concatenate + split. Register the four bytes so they are
                    // valid on the same edge READY is entered, along with
                    // o_ready.
                    o_vector_1   <= concat_bus[31:24];
                    o_vector_2   <= concat_bus[23:16];
                    o_vector_3   <= concat_bus[15:8];
                    o_vector_4   <= concat_bus[7:0];
                    o_ready      <= 1'b1;
                    o_error      <= 1'b0;
                    o_fsm_status <= READY;
                end

                READY: begin
                    // Outputs valid; wait for the 1-cycle i_ack pulse.
                    o_ready <= 1'b1;
                    o_error <= 1'b0;
                    if (i_ack) begin
                        o_ready      <= 1'b0;
                        o_fsm_status <= IDLE;
                    end
                    else begin
                        o_fsm_status <= READY;
                    end
                end

                FAULT: begin
                    // i_fault is deasserted on this branch (outer test handles
                    // the asserted case). Keep error high and outputs at
                    // default; leave FAULT only when i_clear is asserted.
                    o_error    <= 1'b1;
                    o_ready    <= 1'b0;
                    o_vector_1 <= 8'd0;
                    o_vector_2 <= 8'd0;
                    o_vector_3 <= 8'd0;
                    o_vector_4 <= 8'd0;
                    if (i_clear) begin
                        o_error      <= 1'b0;
                        o_fsm_status <= IDLE;
                    end
                    else begin
                        o_fsm_status <= FAULT;
                    end
                end

                default: begin
                    o_fsm_status <= IDLE;
                    o_ready      <= 1'b0;
                    o_error      <= 1'b0;
                end
            endcase
        end
    end

endmodule

// ============================================================================
// advanced_decimator_with_adaptive_peak_detection
// ----------------------------------------------------------------------------
// Packed-bus decimation + signed peak detection.
//
// Behavior (per spec):
//   1. Register the packed input bus (and valid) on the rising edge of clk;
//      an asynchronous active-high reset clears both -> fixed 1-cycle latency.
//   2. Combinationally unpack the registered bus into N signed samples.
//   3. Decimation: select one sample every DEC_FACTOR positions -> N/DEC_FACTOR
//      samples.
//   4. Peak detection: signed maximum over the decimated samples (starts from
//      the first decimated sample, then keeps the running max).
//   5. Pack the decimated samples into data_out (combinational).
//   6. valid_out is the registered valid_in (cleared on reset).
//
//   data_out and peak_value are combinational functions of the registered
//   input, so they are valid in the same cycle valid_out asserts (latency = 1).
//
// Indexing convention is taken from the spec's worked example:
//   data_in  = {16'd10,16'd20,16'd30,16'd40,16'd50,16'd60,16'd70,16'd80}
//   data_out = {16'd10,16'd50},  peak_value = 16'd50
// So logical sample index 0 = the FIRST-written element = the MOST-significant
// slot of the packed bus. Input sample k occupies bits
// [(N-1-k)*DATA_WIDTH +: DATA_WIDTH]; decimated sample q = input sample
// q*DEC_FACTOR and is packed at [(DEC_N-1-q)*DATA_WIDTH +: DATA_WIDTH] of
// data_out. (Verified against the example: MSB-first reproduces {10,50}/50;
// a naive LSB-first mapping would wrongly yield {40,80}/80.)
// ============================================================================
module advanced_decimator_with_adaptive_peak_detection #(
    parameter integer N          = 8,   // total number of input samples (> 1)
    parameter integer DATA_WIDTH = 16,  // bit-width of each sample (> 1)
    parameter integer DEC_FACTOR = 4    // decimation factor (integer divisor of N)
) (
    input  wire                                     clk,
    input  wire                                     reset,      // async, active-high
    input  wire                                     valid_in,
    input  wire  [DATA_WIDTH*N-1:0]                 data_in,    // N packed signed samples
    output reg                                      valid_out,
    output reg   [DATA_WIDTH*(N/DEC_FACTOR)-1:0]    data_out,   // N/DEC_FACTOR packed samples
    output reg   [DATA_WIDTH-1:0]                   peak_value  // signed peak of decimated set
);

    // Number of decimated output samples.
    localparam integer DEC_N = N / DEC_FACTOR;

    // ------------------------------------------------------------------
    // 1) Input registering (1-cycle pipeline): packed data + valid together,
    //    asynchronous active-high reset clears both.
    // ------------------------------------------------------------------
    reg [DATA_WIDTH*N-1:0] data_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg  <= {(DATA_WIDTH*N){1'b0}};
            valid_out <= 1'b0;
        end else begin
            data_reg  <= data_in;
            valid_out <= valid_in;
        end
    end

    // ------------------------------------------------------------------
    // 2)-5) Combinational unpack / decimate / signed peak / pack from data_reg.
    // ------------------------------------------------------------------
    integer                      q;
    reg signed [DATA_WIDTH-1:0]  dec_sample;  // current decimated sample
    reg signed [DATA_WIDTH-1:0]  peak_c;      // running signed maximum

    always @(*) begin
        data_out = {(DATA_WIDTH*DEC_N){1'b0}};

        // Initialize peak with the first decimated sample (input sample index 0,
        // i.e. the most-significant slot of the packed bus).
        peak_c = $signed(data_reg[(N-1)*DATA_WIDTH +: DATA_WIDTH]);

        for (q = 0; q < DEC_N; q = q + 1) begin
            // decimated sample q = input sample (q*DEC_FACTOR)
            dec_sample = $signed(data_reg[(N-1-(q*DEC_FACTOR))*DATA_WIDTH +: DATA_WIDTH]);

            // pack MSB-first: logical index 0 in the most-significant slot
            data_out[(DEC_N-1-q)*DATA_WIDTH +: DATA_WIDTH] = dec_sample;

            // signed running maximum over the decimated samples
            if (dec_sample > peak_c)
                peak_c = dec_sample;
        end

        peak_value = peak_c;
    end

endmodule


