module sgd_linear_regression #(
    parameter DATA_WIDTH = 16,
    parameter LEARNING_RATE = 3'd1
) (
    input  logic clk,                               // Clock
    input  logic reset,                             // Asynchronous reset
    input  logic signed [DATA_WIDTH-1:0] x_in,      // Input data (x)
    input  logic signed [DATA_WIDTH-1:0] y_true,    // True output (target)
    output logic signed [DATA_WIDTH-1:0] w,     // Trained weight
    output logic signed [DATA_WIDTH-1:0] b      // Trained bias
);
    localparam NBW_PRED  = 2*DATA_WIDTH + 1;
    localparam NBW_ERROR = NBW_PRED + 1;
    localparam NBW_DELTA = 3 + NBW_ERROR + DATA_WIDTH;

    // Learning rate as a signed constant (allowed values 0, 1, 2 -> MSB is 0,
    // so zero-extension keeps the value; a signed operand is required so the
    // delta multiplications stay fully signed and sign-extend a negative error).
    localparam logic signed [3:0] LR_S = {1'b0, LEARNING_RATE[2:0]};

    // Intermediate values
    logic signed [NBW_PRED-1:0] y_pred;
    logic signed [NBW_ERROR-1:0] error;
    logic signed [NBW_DELTA-1:0] delta_w;
    logic signed [NBW_DELTA-1:0] delta_b;

    // Predicted output caculation
    always_comb begin
      y_pred = (w * x_in) + b;
    end

    // Error calculation: error = y_true - y_pred (combinational, zero latency)
    always_comb begin
      error = y_true - y_pred;
    end

    // Weight and bias update terms (combinational, zero latency)
    //   delta_w = LEARNING_RATE * error * x_in
    //   delta_b = LEARNING_RATE * error
    always_comb begin
      delta_w = LR_S * error * x_in;
      delta_b = LR_S * error;
    end

    // Register update: w and b take the DATA_WIDTH least significant bits of
    // the full-precision sums; asynchronous active-high reset clears both.
    always_ff @(posedge clk or posedge reset) begin
      if (reset) begin
        w <= '0;
        b <= '0;
      end else begin
        w <= DATA_WIDTH'(w + delta_w);
        b <= DATA_WIDTH'(b + delta_b);
      end
    end

endmodule

// -----------------------------------------------------------------------------
// data_bus_controller
// -----------------------------------------------------------------------------
// Two master ready-valid interfaces (m0, m1) arbitrated onto a single slave
// ready-valid interface.
//
//  - The slave's ready (s_read) is transferred directly to both masters'
//    ready outputs (m0_read, m1_read).
//  - A master transaction is accepted on a cycle where its valid and its
//    ready are both high; the accepted transaction is presented to the slave
//    one cycle later (one-cycle latency, registered s_valid / s_data).
//  - Different-cycle requests are served first come, first served.
//  - If both masters present a valid transaction in the SAME cycle, the
//    parameter AFINITY selects the winner:
//        AFINITY == 0 -> m0 transaction is driven to the slave, m1 ignored
//        AFINITY == 1 -> m1 transaction is driven to the slave, m0 ignored
//  - Once s_valid is asserted, s_data is held stable until the slave accepts
//    the transfer (s_valid && s_read in the same cycle).
// -----------------------------------------------------------------------------
module data_bus_controller #(
  parameter AFINITY = 0
  )(
  input         clk      ,
  input         rst_n    ,

  output        m0_read  ,
  input         m0_valid ,
  input [31:0]  m0_data  ,

  output        m1_read  ,
  input         m1_valid ,
  input [31:0]  m1_data  ,

  input         s_read   ,
  output        s_valid  ,
  output [31:0] s_data
);

  // ---------------------------------------------------------------------------
  // Slave ready transferred to both masters' ready outputs
  // ---------------------------------------------------------------------------
  assign m0_read = s_read;
  assign m1_read = s_read;

  // ---------------------------------------------------------------------------
  // Handshake detection (valid && ready high in the same cycle)
  // ---------------------------------------------------------------------------
  wire m0_hs = m0_valid & m0_read;
  wire m1_hs = m1_valid & m1_read;

  // Winner selection:
  //  - both masters handshake in the same cycle -> AFINITY decides
  //      (the losing master's transaction is ignored)
  //  - otherwise the single handshaking master is taken (FCFS)
  wire        take_m1  = (m0_hs & m1_hs) ? (AFINITY != 0) : m1_hs;
  wire [31:0] mux_data = take_m1 ? m1_data : m0_data;

  // ---------------------------------------------------------------------------
  // One-cycle-latency registered slave interface.
  // The registered beat is held stable until the slave takes it
  // (s_valid && s_read handshake), per the ready-valid protocol.
  // ---------------------------------------------------------------------------
  reg        s_valid_q;
  reg [31:0] s_data_q;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      s_valid_q <= 1'b0;
      s_data_q  <= 32'd0;
    end else begin
      if (m0_hs | m1_hs) begin
        // New transaction accepted this cycle. The slave was ready this
        // cycle (m*_read == s_read), so any currently presented beat is
        // consumed in this same cycle; loading a new beat is safe.
        s_valid_q <= 1'b1;
        s_data_q  <= mux_data;
      end else if (s_valid_q && s_read) begin
        // Presented beat consumed by the slave, no new transaction.
        s_valid_q <= 1'b0;
      end
      // else: hold s_valid_q / s_data_q until the slave accepts.
    end
  end

  assign s_valid = s_valid_q;
  assign s_data  = s_data_q;

endmodule

// ---------------------------------------------------------------------------
// Digital Dice Roller
// ---------------------------------------------------------------------------
// Controls rolling of a 6-sided die.
//  - FSM with two states: IDLE and ROLLING.
//  - While `button` is HIGH the internal 3-bit register `counter` cycles
//    through the dice values 1..6 (one step per positive clock edge,
//    wrapping 6 -> 1).
//  - When `button` returns LOW the FSM goes back to IDLE and `dice_value`
//    presents the last counter value reached while rolling (always 1..6).
//  - Asynchronous active-LOW reset `reset_n` keeps `dice_value` at 000.
// ---------------------------------------------------------------------------
module digital_dice_roller (
    input  wire       clk,        // system clock
    input  wire       reset_n,    // asynchronous active-low reset
    input  wire       button,     // roll while HIGH, show result when LOW
    output reg  [2:0] dice_value  // dice result, valid values 1..6
);

    // FSM state encoding
    localparam IDLE    = 1'b0;
    localparam ROLLING = 1'b1;

    reg       state;
    reg [2:0] counter;  // internal 3-bit counter cycling through 1..6

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state      <= IDLE;
            counter    <= 3'd0;
            dice_value <= 3'd0;
        end else begin
            case (state)
                IDLE: begin
                    // dice_value remains constant in IDLE.
                    if (button) begin
                        // First rolling step counts 1.
                        state   <= ROLLING;
                        counter <= 3'd1;
                    end
                end
                ROLLING: begin
                    if (button) begin
                        // Cycle 1..6, wrapping 6 -> 1.
                        counter <= (counter == 3'd6) ? 3'd1 : counter + 3'd1;
                    end else begin
                        // Button released: present the last rolled value
                        // (always within 1..6) and return to IDLE.
                        state      <= IDLE;
                        dice_value <= counter;
                        counter    <= 3'd0;
                    end
                end
                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule


