    localparam [7:0] ADDR_TEMP_MED    = 8'h0b;
    localparam [7:0] ADDR_TEMP_HIGH   = 8'h0c;
    localparam [7:0] ADDR_TEMP_ADC_IN = 8'h0f;

    // Duty-cycle counter load values (out of a 256-clock PWM period)
    localparam [7:0] DUTY_OFF = 8'd0;    // fan disabled (reset)
    localparam [7:0] DUTY_25  = 8'd64;   // 25%  : high 64,  low 192
    localparam [7:0] DUTY_50  = 8'd128;  // 50%  : high 128, low 128
    localparam [7:0] DUTY_75  = 8'd192;  // 75%  : high 192, low 64
    localparam [7:0] DUTY_100 = 8'd255;  // 100% : high 255, low 1

    // ------------------------------------------------------------------
    // Internal registers (names per specification)
    // ------------------------------------------------------------------
    reg [7:0] TEMP_LOW;        // 0x0a : max temperature considered "low"
    reg [7:0] TEMP_MED;        // 0x0b : max temperature considered "medium"
    reg [7:0] TEMP_HIGH;       // 0x0c : max temperature considered "high"
    reg [7:0] temp_adc_in;     // 0x0f : current temperature reading (ADC)

    reg [7:0] pwm_duty_cycle;  // current PWM duty (counter load value)
    reg [7:0] pwm_counter;     // free-running 8-bit PWM period counter

    // ------------------------------------------------------------------
    // Address decode (prepared during the setup phase - combinational)
    // ------------------------------------------------------------------
    wire addr_valid = (paddr == ADDR_TEMP_LOW ) ||
                      (paddr == ADDR_TEMP_MED ) ||
                      (paddr == ADDR_TEMP_HIGH) ||
                      (paddr == ADDR_TEMP_ADC_IN);

    // ------------------------------------------------------------------
    // APB write: performed in the access phase (psel & penable & pwrite).
    // An invalid address performs no register update (error is flagged
    // on pslverr instead).
    // ------------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            TEMP_LOW    <= 8'h00;
            TEMP_MED    <= 8'h00;
            TEMP_HIGH   <= 8'h00;
            temp_adc_in <= 8'h00;
        end else if (psel && penable && pwrite) begin
            case (paddr)
                ADDR_TEMP_LOW:    TEMP_LOW    <= pwdata;
                ADDR_TEMP_MED:    TEMP_MED    <= pwdata;
                ADDR_TEMP_HIGH:   TEMP_HIGH   <= pwdata;
                ADDR_TEMP_ADC_IN: temp_adc_in <= pwdata;
                default:          ; // invalid address: no write
            endcase
        end
    end

    // ------------------------------------------------------------------
    // APB response: zero-wait-state slave.
    //   - pready asserted only during the access phase
    //   - pslverr asserted during the access phase for invalid addresses
    //   - both cleared whenever the module is not selected (psel = 0)
    //   - prdata is a 0-cycle combinational read of the live registers
    // ------------------------------------------------------------------
    always @(*) begin
        pready  = psel && penable;
        pslverr = psel && penable && !addr_valid;
        prdata  = 8'h00;
        if (psel && !pwrite) begin
            case (paddr)
                ADDR_TEMP_LOW:    prdata = TEMP_LOW;
                ADDR_TEMP_MED:    prdata = TEMP_MED;
                ADDR_TEMP_HIGH:   prdata = TEMP_HIGH;
                ADDR_TEMP_ADC_IN: prdata = temp_adc_in;
                default:          prdata = 8'h00; // invalid address reads 0
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Temperature-based fan speed selection.
    //   TEMP_x holds the MAXIMUM temperature considered as that band:
    //     temp <= TEMP_LOW              -> low    (25%)
    //     TEMP_LOW  < temp <= TEMP_MED  -> medium (50%)
    //     TEMP_MED  < temp <= TEMP_HIGH -> high   (75%)
    //     temp >  TEMP_HIGH             -> full   (100%)
    //   Reset disables the fan (pwm_duty_cycle = 0).
    // ------------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset)
            pwm_duty_cycle <= DUTY_OFF;
        else if (temp_adc_in <= TEMP_LOW)
            pwm_duty_cycle <= DUTY_25;
        else if (temp_adc_in <= TEMP_MED)
            pwm_duty_cycle <= DUTY_50;
        else if (temp_adc_in <= TEMP_HIGH)
            pwm_duty_cycle <= DUTY_75;
        else
            pwm_duty_cycle <= DUTY_100;
    end

    // ------------------------------------------------------------------
    // PWM period counter: free-running 0..255 (256-clock period).
    // ------------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset)
            pwm_counter <= 8'd0;
        else
            pwm_counter <= pwm_counter + 8'd1;
    end

    // ------------------------------------------------------------------
    // PWM output: high for pwm_duty_cycle clocks out of every 256.
    //   duty 64  -> high 64 / low 192
    //   duty 128 -> high 128 / low 128
    //   duty 192 -> high 192 / low 64
    //   duty 255 -> high 255 / low 1
    //   duty 0   -> output disabled (also holds 0 during reset)
    // ------------------------------------------------------------------
    always @(*) begin
        fan_pwm_out = (pwm_counter < pwm_duty_cycle);
    end

endmodule

// fibonacci_series
// 32-bit Fibonacci series generator with overflow detection and auto-restart.
//
// Behaviour (per specification):
//   - Starts from F(0)=0, F(1)=1. RegA holds F(n-2), RegB holds F(n-1).
//   - Each rising clock edge: next_fib = RegA + RegB (33-bit sum to expose carry).
//   - Normal advance: RegA<=RegB, RegB<=next_fib, fib_out<=next_fib.
//   - Overflow detect (next_fib[32]==1): set overflow_detected, hold the last
//     valid Fibonacci value (RegB) on fib_out; overflow_flag stays 0 this cycle.
//   - One cycle later (overflow_detected==1): assert overflow_flag, reset fib_out
//     to 0 and restart the sequence (RegA=0, RegB=1); clear overflow_detected.
//   - overflow_flag is thus a one-cycle pulse asserted the cycle after detection,
//     coincident with the automatic restart; it returns low once the sequence
//     resumes normal operation.
//
// Reset (rst, active-high, synchronous): RegA=0, RegB=1, fib_out=0,
//   overflow_flag=0, overflow_detected=0.

module fibonacci_series (
    input  wire        clk,
    input  wire        rst,
    output reg  [31:0] fib_out,
    output reg         overflow_flag
);

    reg [31:0] RegA;              // F(n-2)
    reg [31:0] RegB;              // F(n-1)
    reg        overflow_detected; // internal: overflow seen, restart pending

    // 33-bit sum so bit [32] is the overflow (carry-out) of the 32-bit addition.
    wire [32:0] next_fib = {1'b0, RegA} + {1'b0, RegB};

    always @(posedge clk) begin
        if (rst) begin
            RegA              <= 32'd0;
            RegB              <= 32'd1;
            fib_out           <= 32'd0;
            overflow_flag     <= 1'b0;
            overflow_detected <= 1'b0;
        end else if (overflow_detected) begin
            // One cycle after overflow: assert the flag and restart the series.
            RegA              <= 32'd0;
            RegB              <= 32'd1;
            fib_out           <= 32'd0;
            overflow_flag     <= 1'b1;
            overflow_detected <= 1'b0;
        end else if (next_fib[32]) begin
            // Overflow this cycle: hold the last valid Fibonacci value, arm flag.
            overflow_detected <= 1'b1;
            fib_out           <= RegB;
            overflow_flag     <= 1'b0;
        end else begin
            // Normal Fibonacci advance.
            RegA              <= RegB;
            RegB              <= next_fib[31:0];
            fib_out           <= next_fib[31:0];
            overflow_flag     <= 1'b0;
        end
    end

endmodule

//======================================================================
// Asynchronous (dual-clock) FIFO
//   - configurable DATA_WIDTH and DEPTH
//   - (ADDR_WIDTH+1)-bit Gray-coded write/read pointers
//   - 2-flop cross-clock synchronizers for each pointer
//   - empty : local read gray == synchronized write gray
//   - full  : local write gray == synchronized read gray with the
//             top TWO bits inverted (Gray-domain form of "MSB differs,
//             all lower bits equal")
//   - combinational read data (r_data is a plain wire output)
//======================================================================
module asynchronous_fifo #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH      = 16
)(
    input  wire                  w_clk,
    input  wire                  w_rst,
    input  wire                  w_inc,
    input  wire [DATA_WIDTH-1:0] w_data,
    input  wire                  r_clk,
    input  wire                  r_rst,
    input  wire                  r_inc,
    output wire                  w_full,
    output wire                  r_empty,
    output wire [DATA_WIDTH-1:0] r_data
);

    // Address width; pointers carry one extra MSB to detect wrap/overflow
    localparam ADDR_WIDTH = $clog2(DEPTH);

    // Storage
    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    //------------------------------------------------------------------
    // Write clock domain: binary + gray pointer, full flag
    //------------------------------------------------------------------
    reg  [ADDR_WIDTH:0]   w_bin, w_gray;
    wire [ADDR_WIDTH:0]   w_bin_next  = w_bin + (w_inc & ~w_full);
    wire [ADDR_WIDTH:0]   w_gray_next = (w_bin_next >> 1) ^ w_bin_next;
    wire [ADDR_WIDTH-1:0] w_addr      = w_bin[ADDR_WIDTH-1:0];

    // synchronized read pointer (into write domain)
    reg  [ADDR_WIDTH:0]   wq1_r_gray, wq2_r_gray;

    reg  w_full_r;
    wire w_full_next = (w_gray_next ==
                        {~wq2_r_gray[ADDR_WIDTH:ADDR_WIDTH-1],
                          wq2_r_gray[ADDR_WIDTH-2:0]});

    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            w_bin  <= {(ADDR_WIDTH+1){1'b0}};
            w_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            w_bin  <= w_bin_next;
            w_gray <= w_gray_next;
        end
    end

    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) w_full_r <= 1'b0;
        else       w_full_r <= w_full_next;
    end

    assign w_full = w_full_r;

    // memory write
    always @(posedge w_clk) begin
        if (w_inc & ~w_full_r)
            mem[w_addr] <= w_data;
    end

    //------------------------------------------------------------------
    // Read clock domain: binary + gray pointer, empty flag
    //------------------------------------------------------------------
    reg  [ADDR_WIDTH:0]   r_bin, r_gray;
    wire [ADDR_WIDTH:0]   r_bin_next  = r_bin + (r_inc & ~r_empty);
    wire [ADDR_WIDTH:0]   r_gray_next = (r_bin_next >> 1) ^ r_bin_next;
    wire [ADDR_WIDTH-1:0] r_addr      = r_bin[ADDR_WIDTH-1:0];

    // synchronized write pointer (into read domain)
    reg  [ADDR_WIDTH:0]   rq1_w_gray, rq2_w_gray;

    reg  r_empty_r;
    wire r_empty_next = (r_gray_next == rq2_w_gray);

    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            r_bin  <= {(ADDR_WIDTH+1){1'b0}};
            r_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            r_bin  <= r_bin_next;
            r_gray <= r_gray_next;
        end
    end

    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) r_empty_r <= 1'b1;
        else       r_empty_r <= r_empty_next;
    end

    assign r_empty = r_empty_r;

    // combinational (first-word-fall-through) read
    assign r_data = mem[r_addr];

    //------------------------------------------------------------------
    // Cross-clock 2-flop synchronizers
    //------------------------------------------------------------------
    // read pointer -> write clock domain
    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            wq1_r_gray <= {(ADDR_WIDTH+1){1'b0}};
            wq2_r_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            wq1_r_gray <= r_gray;
            wq2_r_gray <= wq1_r_gray;
        end
    end

    // write pointer -> read clock domain
    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            rq1_w_gray <= {(ADDR_WIDTH+1){1'b0}};
            rq2_w_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            rq1_w_gray <= w_gray;
            rq2_w_gray <= rq1_w_gray;
        end
    end

endmodule


